// ═══════════════════════════════════════════════════════════════════
// BUILD 1: FinaultRouter — Express-style router (replaces Hono, zero deps)
// ═══════════════════════════════════════════════════════════════════

class FinaultRouter {
  constructor() {
    this.routes = [];
    this.globalMiddleware = [];
  }

  use(...handlers) {
    this.globalMiddleware.push(...handlers);
  }

  add(method, pattern, ...handlers) {
    const regexStr = '^' + pattern
      .replace(/:([a-zA-Z_]+)/g, '(?<$1>[^/]+)')
      .replace(/\*/g, '.*') + '$';
    this.routes.push({
      method: method.toUpperCase(),
      pattern: new RegExp(regexStr),
      handlers: [...this.globalMiddleware, ...handlers],
      raw: pattern
    });
  }

  get(p, ...h) { this.add('GET', p, ...h); }
  post(p, ...h) { this.add('POST', p, ...h); }
  put(p, ...h) { this.add('PUT', p, ...h); }
  delete(p, ...h) { this.add('DELETE', p, ...h); }
  options(p, ...h) { this.add('OPTIONS', p, ...h); }

  async handle(request, env, ctx) {
    const url = new URL(request.url);
    const method = request.method.toUpperCase();

    for (const route of this.routes) {
      if (route.method !== method && route.method !== 'ALL') continue;
      const match = route.pattern.exec(url.pathname);
      if (!match) continue;

      const fCtx = {
        req: request,
        env,
        ctx,
        params: match.groups || {},
        url,
        headers: Object.fromEntries(request.headers),
        state: {},
      };

      let index = 0;
      const next = async () => {
        if (index < route.handlers.length) {
          const handler = route.handlers[index++];
          return await handler(fCtx, next);
        }
      };

      const response = await next();
      if (response instanceof Response) return response;
    }

    return null; // No match — fall through to legacy handler
  }
}

// Router instance (routes registered by future builds)
const finaultRouter = new FinaultRouter();

// ═══════════════════════════════════════════════════════════════════
// BUILD 3: Rate Limiting Hardening — Per-category limits
// ═══════════════════════════════════════════════════════════════════

const RATE_LIMITS = {
  proxy:       { limit: 1000, window: 60 },
  management:  { limit: 60,   window: 60 },
  export:      { limit: 10,   window: 60 },
  compliance:  { limit: 20,   window: 60 },
  close_pack:  { limit: 5,    window: 3600 },
  auth:        { limit: 20,   window: 60 },
  public:      { limit: 100,  window: 60 },
};

class FinaultRateLimiter {
  static async check(env, orgId, category, limit, windowSec = 60) {
    if (!env.KV_CACHE && !env.FINAULT_KV) return { allowed: true, remaining: limit - 1, resetAt: 0 };
    const kv = env.KV_CACHE || env.FINAULT_KV;
    const window = Math.floor(Date.now() / (windowSec * 1000));
    const key = `rl:${category}:${orgId}:${window}`;

    const current = parseInt(await kv.get(key) || '0');
    if (current >= limit) {
      return {
        allowed: false,
        remaining: 0,
        resetAt: (window + 1) * windowSec,
        retryAfter: Math.ceil(((window + 1) * windowSec * 1000 - Date.now()) / 1000)
      };
    }

    await kv.put(key, String(current + 1), {
      expirationTtl: windowSec * 2
    });

    return {
      allowed: true,
      remaining: limit - current - 1,
      resetAt: (window + 1) * windowSec,
    };
  }

  static errorResponse(result) {
    return new Response(JSON.stringify({
      error: 'Rate limit exceeded',
      retry_after: result.retryAfter,
    }), {
      status: 429,
      headers: {
        'Content-Type': 'application/json',
        'Retry-After': String(result.retryAfter),
        'X-RateLimit-Remaining': '0',
        'X-RateLimit-Reset': String(result.resetAt),
      }
    });
  }
}

// Rate limit middleware factory for FinaultRouter
function rateLimitMiddleware(category) {
  return async (c, next) => {
    const orgId = c.state.org?.id || c.req.headers.get('CF-Connecting-IP') || 'anon';
    const config = RATE_LIMITS[category];
    if (!config) return await next();
    const result = await FinaultRateLimiter.check(c.env, orgId, category, config.limit, config.window);

    if (!result.allowed) {
      return FinaultRateLimiter.errorResponse(result);
    }

    const response = await next();
    if (response instanceof Response) {
      const newResponse = new Response(response.body, response);
      newResponse.headers.set('X-RateLimit-Remaining', String(result.remaining));
      return newResponse;
    }
    return response;
  };
}

/**
 * Check if a path matches a pattern (supports wildcards)
 */
const pathMatches = (path, pattern) => {
  if (pattern === path) return true;
  if (pattern.includes('*')) {
    const regex = new RegExp(
      `^${pattern.replace(/\//g, '\\/').replace(/\*/g, '.*')}$`
    );
    return regex.test(path);
  }
  return false;
};

/**
 * Check if path is public (no auth required)
 */
const isPublicEndpoint = (path) => {
  return PUBLIC_ENDPOINTS.some(pattern => pathMatches(path, pattern));
};

/**
 * Verify user belongs to organization
 * Useful for multi-tenant isolation
 */
const userBelongsToOrg = (request, resourceOrgId) => {
  if (!request._user) return false;
  if (request._user.role === 'superadmin') return true;
  return request._user.orgId === resourceOrgId;
};

/**
 * Get organization ID ONLY from authenticated JWT context (F-2 fix)
 * NEVER reads org_id from request body or untrusted sources
 *
 * @param {Object} request - Request object with _user context from JWT
 * @returns {string} Organization ID from JWT
 * @throws {Error} If user not authenticated or org_id missing
 */
const getOrgIdFromAuth = (request) => {
  if (!request._user || !request._user.orgId) {
    throw new Error(
      'Authentication required: No valid organization in JWT token. ' +
      'Please provide a valid Bearer token.'
    );
  }

  if (typeof request._user.orgId !== 'string' || request._user.orgId.trim() === '') {
    throw new Error('Invalid orgId in JWT token');
  }

  return request._user.orgId;
};

/**
 * Enhanced version that falls back to master account ONLY if service_role key present
 * (for internal service-to-service communication)
 *
 * @param {Object} request - Request with _user context
 * @param {string} serviceRoleKey - Environment variable for service role validation
 * @returns {Promise<{orgId: string, authenticated: boolean}>}
 */
const getOrgIdFromAuthWithServiceRole = async (request, serviceRoleKey) => {
  const MASTER_ACCOUNT_UUID = 'bc3341ee-6061-408f-b13c-547c8b297e52';

  try {
    // First try JWT-based authentication
    const orgId = getOrgIdFromAuth(request);
    return { orgId, authenticated: true };
  } catch (error) {
    // Check if valid service_role is present (internal service calls only)
    if (serviceRoleKey) {
      const serviceHeader = request.headers.get('X-Service-Role');
      if (serviceHeader === serviceRoleKey) {
        console.log('[AUTH] Service role fallback to master account');
        return { orgId: MASTER_ACCOUNT_UUID, authenticated: false, isService: true };
      }
    }

    // No valid auth or service role - throw error
    throw error;
  }
};

/**
 * Authenticate request using JWT from Authorization header
 * Sets request._user with validated JWT payload
 *
 * @param {Object} request - Cloudflare Workers Request
 * @param {string} jwtSecret - JWT secret for verification
 * @returns {Promise<boolean>} True if authenticated, false if public endpoint
 * @throws {Error} If token invalid and not public endpoint
 */
const authenticateRequest = async (request, jwtSecret, env) => {
  const url = new URL(request.url);
  const path = url.pathname;

  // Skip auth for public endpoints
  if (isPublicEndpoint(path)) {
    request._user = null;
    return true;
  }

  // ═══ API KEY AUTH (fk_ keys) ═══
  // Check X-Finault-API-Key header or Authorization: Bearer fk_...
  const finaultApiKey = request.headers.get('X-Finault-API-Key') ||
                        request.headers.get('x-finault-key');
  const authHeader = request.headers.get('Authorization') || '';
  const bearerMatch = authHeader.match(/^Bearer\s+(\S+)$/);
  const bearerToken = bearerMatch ? bearerMatch[1] : null;

  // Determine if we have a Finault API key (fk_ or fnlt_ prefix)
  const isFinaultKey = (k) => k && (k.startsWith('fk_') || k.startsWith('fnlt_'));
  const fkKey = isFinaultKey(finaultApiKey) ? finaultApiKey
              : isFinaultKey(bearerToken) ? bearerToken
              : null;

  if (fkKey && env && env.SUPABASE_URL && ((env.SUPABASE_SERVICE_KEY || env.SUPABASE_KEY) || env.SUPABASE_KEY)) {
    try {
      // ═══ TEST MODE DETECTION ═══
      // Test keys follow format: fk_test_ + 24+ alphanumeric characters
      const isTestMode = fkKey.startsWith('fk_test_');
      if (isTestMode) {
        const testKeyPattern = /^fk_test_[a-zA-Z0-9]{24,}$/;
        if (!testKeyPattern.test(fkKey)) {
          console.error(`[AUTH] Invalid test key format: ${fkKey.substring(0, 15)}...`);
          throw new Error('Invalid test API key format');
        }

        console.log(`[AUTH] Test mode key authenticated: ${fkKey.substring(0, 15)}...`);

        // Set user context for test mode (no Supabase lookup needed)
        request._user = {
          userId: 'test_org',
          orgId: 'test_org',
          email: null,
          name: 'Test Mode API Key',
          role: 'api_key',
          permissions: [],
          authMethod: 'api_key_test',
          keyId: null,
          isTest: true
        };

        // Test mode flag for proxy functions
        request._testMode = true;

        // Store the provider key separately for proxy use (optional in test mode)
        const providerKey = request.headers.get('X-Provider-Key') ||
                            (bearerToken && !bearerToken.startsWith('fk_') ? bearerToken : null);
        if (providerKey) {
          request._providerKey = providerKey;
        }

        return true;
      }

      // ═══ PRODUCTION KEY VALIDATION ═══
      // Hash the API key to match against stored key_hash
      const keyHashBuf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(fkKey));
      const keyHashHex = Array.from(new Uint8Array(keyHashBuf)).map(b => b.toString(16).padStart(2, '0')).join('');

      // Look up key in Supabase api_keys table
      // Use service role key (bypasses RLS) with fallback to anon key
      const supabaseKey = (env.SUPABASE_SERVICE_KEY || env.SUPABASE_KEY) || env.SUPABASE_KEY;
      const keyResp = await fetch(
        `${env.SUPABASE_URL}/rest/v1/api_keys?key_hash=eq.${keyHashHex}&enabled=eq.true&select=id,org_id,name`,
        {
          headers: {
            'apikey': supabaseKey,
            'Authorization': `Bearer ${supabaseKey}`
          }
        }
      );

      if (keyResp.ok) {
        const keys = await keyResp.json();
        console.log(`[AUTH] API key lookup: hash=${keyHashHex.substring(0, 16)}... results=${keys?.length || 0} keyUsed=${supabaseKey ? 'service' : 'anon'}`);
        if (keys && keys.length > 0) {
          const keyRecord = keys[0];
          const resolvedOrgId = keyRecord.org_id || keyRecord.organization_id;
          console.log(`[AUTH] API key authenticated: ${fkKey.substring(0, 10)}... org=${resolvedOrgId}`);

          // Set user context from API key
          request._user = {
            userId: resolvedOrgId,
            orgId: resolvedOrgId,
            email: null,
            name: keyRecord.name || 'API Key User',
            role: 'api_key',
            permissions: [],
            authMethod: 'api_key',
            keyId: keyRecord.id
          };

          // Store the provider key separately for proxy use
          // Provider key comes from: X-Provider-Key header, or Authorization header (if not fk_)
          const providerKey = request.headers.get('X-Provider-Key') ||
                              (bearerToken && !bearerToken.startsWith('fk_') ? bearerToken : null);
          if (providerKey) {
            request._providerKey = providerKey;
          }

          return true;
        }
      }

      // Key not found or lookup failed
      const errBody = !keyResp.ok ? await keyResp.text().catch(() => '') : '';
      console.error(`[AUTH] API key lookup failed: status=${keyResp.status} body=${errBody.substring(0, 200)} hash=${keyHashHex.substring(0, 16)}`);
      throw new Error('Invalid API key');
    } catch (error) {
      console.error(`[AUTH] API key auth failed for ${path}: ${error.message}`);
      throw error;
    }
  }

  // ═══ JWT AUTH (Supabase Bearer tokens) ═══
  if (!bearerMatch) {
    throw new Error('Missing or invalid Authorization header (Bearer token or X-Finault-API-Key required)');
  }

  try {
    const token = bearerToken;
    const payload = await jwtUtils.verify(token, jwtSecret);

    // Map Supabase JWT claims to Finault user context
    // Supabase uses: sub (user id), email, app_metadata, user_metadata
    // Finault expects: userId, orgId, email, name, role, permissions
    const userId = payload.userId || payload.sub || payload.user_id;
    const orgId = payload.orgId || payload.app_metadata?.org_id || payload.app_metadata?.organization_id || userId;
    const email = payload.email || payload.user_metadata?.email;
    const name = payload.name || payload.user_metadata?.full_name || payload.user_metadata?.name || email;
    const role = payload.role || payload.app_metadata?.role || payload.user_role || 'viewer';
    const permissions = payload.permissions || payload.app_metadata?.permissions || [];

    if (!userId) {
      throw new Error('Token missing required claims (userId/sub)');
    }

    // Attach user context to request (use _user to avoid conflicts)
    request._user = {
      userId,
      orgId: orgId || userId, // Fall back to userId if no org
      email,
      name,
      role,
      permissions,
      iat: payload.iat,
      exp: payload.exp,
    };

    return true;
  } catch (error) {
    console.error(`[AUTH] Authentication failed for ${path}: ${error.message}`);
    throw error;
  }
};

// ═══════════════════════════════════════════════════════════════════
// BUILD 4: KV Cleanup — Read-Through Cache + Batched Writes
// ═══════════════════════════════════════════════════════════════════

async function cachedRead(env, kvKey, supabaseQuery, ttlSec = 300) {
  const kv = env.KV_CACHE || env.FINAULT_KV;
  if (kv) {
    const cached = await kv.get(kvKey);
    if (cached) {
      try { return JSON.parse(cached); } catch { /* corrupted cache, fall through */ }
    }
  }

  const data = await supabaseQuery();
  if (data && kv) {
    // Populate cache asynchronously
    try {
      const ctx = env._ctx || globalThis.__finaultCtx;
      const putOp = kv.put(kvKey, JSON.stringify(data), { expirationTtl: ttlSec });
      if (ctx && ctx.waitUntil) {
        ctx.waitUntil(putOp);
      } else {
        await putOp;
      }
    } catch { /* cache write failure is non-fatal */ }
  }
  return data;
}

function invalidateCache(env, kvKey) {
  const kv = env.KV_CACHE || env.FINAULT_KV;
  if (kv) {
    try {
      const ctx = env._ctx || globalThis.__finaultCtx;
      const delOp = kv.delete(kvKey);
      if (ctx && ctx.waitUntil) ctx.waitUntil(delOp);
    } catch { /* non-fatal */ }
  }
}

// ── Batched cost accumulator ──
const pendingCosts = new Map();
let requestsSinceFlush = 0;

function accumulateCost(orgId, customerId, cost) {
  const key = `${orgId}:${customerId || 'all'}:${currentCostMonth()}`;
  pendingCosts.set(key, (pendingCosts.get(key) || 0) + cost);
}

function currentCostMonth() {
  const d = new Date();
  return `${d.getUTCFullYear()}-${String(d.getUTCMonth() + 1).padStart(2, '0')}`;
}

async function flushCosts(env) {
  if (pendingCosts.size === 0) return;
  const batch = new Map(pendingCosts);
  pendingCosts.clear();

  const supabaseUrl = env.SUPABASE_URL;
  const supabaseKey = env.SUPABASE_SERVICE_KEY || env.SUPABASE_ANON_KEY;
  if (!supabaseUrl || !supabaseKey) return;

  for (const [key, amount] of batch) {
    const [orgId, customerId, month] = key.split(':');
    try {
      await fetch(`${supabaseUrl}/rest/v1/rpc/increment_spend`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'apikey': supabaseKey,
          'Authorization': `Bearer ${supabaseKey}`,
        },
        body: JSON.stringify({
          p_org_id: orgId,
          p_customer_id: customerId === 'all' ? null : customerId,
          p_month: month,
          p_amount: amount
        })
      });
    } catch (e) {
      // Put back on failure for next flush
      pendingCosts.set(key, (pendingCosts.get(key) || 0) + amount);
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
// BUILD 5: Security Headers Middleware
// ═══════════════════════════════════════════════════════════════════

async function securityHeadersMiddleware(c, next) {
  const response = await next();
  if (!(response instanceof Response)) return response;
  const r = new Response(response.body, response);
  r.headers.set('X-Content-Type-Options', 'nosniff');
  r.headers.set('X-Frame-Options', 'DENY');
  r.headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  r.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
  r.headers.set('X-XSS-Protection', '1; mode=block');
  r.headers.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  return r;
}

// Apply security headers to all responses (legacy handler)
function applySecurityHeaders(response) {
  if (!(response instanceof Response)) return response;
  const r = new Response(response.body, response);
  r.headers.set('X-Content-Type-Options', 'nosniff');
  r.headers.set('X-Frame-Options', 'DENY');
  r.headers.set('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  r.headers.set('Referrer-Policy', 'strict-origin-when-cross-origin');
  r.headers.set('X-XSS-Protection', '1; mode=block');
  r.headers.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  return r;
}

