// Service binding helper for intelligence worker delegation
async function delegateToIntelligence(env, action, payload) {
  // If INTELLIGENCE service binding exists, delegate non-critical path work
  if (env.INTELLIGENCE) {
    try {
      return await env.INTELLIGENCE.fetch(new Request(`https://intelligence/${action}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      }));
    } catch (e) {
      console.error(`Intelligence delegation failed: ${e.message}`);
    }
  }
  // Fallback: handle inline (current behavior)
  return null;
}

// After seal creation, offload non-critical work
let requestsSinceFlush = 0;

async function postSealProcessing(env, ctx, orgId, sealData) {
  const tasks = [];

  // Broadcast to dashboard (Build 7)
  if (typeof broadcastSealEvent === 'function') {
    tasks.push(broadcastSealEvent(env, orgId, sealData));
  }

  // Check webhook triggers (Build 12)
  if (sealData.margin_pct !== null && sealData.margin_pct < 0) {
    if (typeof fireWebhook === 'function') {
      tasks.push(fireWebhook(env, orgId, 'customer.underwater', {
        seal_id: sealData.seal_id, customer_id: sealData.customer_id, margin_pct: sealData.margin_pct
      }));
    }
  }
  if (sealData.dark_debt_score && sealData.dark_debt_score > 50) {
    if (typeof fireWebhook === 'function') {
      tasks.push(fireWebhook(env, orgId, 'dark_debt.critical', {
        seal_id: sealData.seal_id, score: sealData.dark_debt_score, risks: sealData.dark_debt_risks
      }));
    }
  }

  // Analytics (Build 19)
  if (typeof writeAnalyticsEvent === 'function') {
    writeAnalyticsEvent(env, orgId, sealData.action, 'POST', sealData.provider, sealData.cost_usd, sealData.latency_ms, sealData.dark_debt_score);
  }

  // Accumulate cost (Build 4)
  if (typeof accumulateCost === 'function') {
    accumulateCost(orgId, sealData.customer_id, sealData.cost_usd || 0);
  }

  // Flush if needed
  requestsSinceFlush++;
  if (requestsSinceFlush >= 50) {
    if (typeof flushCosts === 'function') {
      tasks.push(flushCosts(env));
    }
    requestsSinceFlush = 0;
  }

  // Run all tasks non-blocking
  if (tasks.length > 0) {
    ctx.waitUntil(Promise.allSettled(tasks));
  }
}

// ═══════════════════════════════════════════════════════════════════
// BUILD 31: Quality Signal — Third axis of WORTH
// ═══════════════════════════════════════════════════════════════════

function computeQualityScore(seal, headers) {
  let score = 1.0;

  // Dark Debt inverse: high debt = low quality
  if (seal.dark_debt_score && seal.dark_debt_score > 0) {
    score -= (seal.dark_debt_score / 100) * 0.5; // Max 0.5 penalty
  }

  // Provider error penalty
  if (seal.error) {
    score -= 0.3;
  }

  // Explicit quality from SDK header
  const explicit = parseFloat(headers?.['x-finault-quality'] || headers?.['X-Finault-Quality']);
  if (!isNaN(explicit) && explicit >= 0 && explicit <= 1) {
    score = explicit; // Override with explicit score
  }

  // Latency penalty (>5s is concerning)
  if (seal.latency_ms && seal.latency_ms > 5000) {
    score -= 0.1;
  }

  return Math.max(0, Math.min(1, Math.round(score * 100) / 100));
}

function qualityTier(score) {
  if (score >= 0.9) return 'excellent';
  if (score >= 0.7) return 'good';
  if (score >= 0.5) return 'acceptable';
  if (score >= 0.3) return 'poor';
  return 'critical';
}

// ═══════════════════════════════════════════════════════════════════
// BUILD 32: Offline-Verifiable Seals — Self-verifying receipts
// ═══════════════════════════════════════════════════════════════════

function buildOfflineProof(seal) {
  const proof = {
    v: 1,
    id: seal.seal_id,
    hash: seal.seal_hash,
    prev: seal.prev_hash,
    seq: seal.sequence,
    ts: seal.timestamp,
    cost: seal.cost_usd,
    revenue: seal.revenue_usd,
    margin: seal.margin_pct,
    model: seal.model,
    provider: seal.provider,
    quality: seal.quality_score,
    dark_debt: seal.dark_debt_score,
  };
  // Base64url encode for header transport
  const json = JSON.stringify(proof);
  const bytes = new TextEncoder().encode(json);
  let binary = '';
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function decodeOfflineProof(base64url) {
  try {
    const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
    const padded = base64 + '='.repeat((4 - base64.length % 4) % 4);
    const binary = atob(padded);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    const json = new TextDecoder().decode(bytes);
    return JSON.parse(json);
  } catch {
    return null;
  }
}

async function verifyOfflineProof(proofData) {
  if (!proofData || proofData.v !== 1) return { valid: false, error: 'Invalid proof version' };

  // Reconstruct the hashable record from proof data
  const hashable = sealCanonicalize ? sealCanonicalize({
    seal_id: proofData.id,
    timestamp: proofData.ts,
    prev_hash: proofData.prev,
    cost_usd: proofData.cost,
    revenue_usd: proofData.revenue,
    margin_pct: proofData.margin,
    model: proofData.model,
    provider: proofData.provider,
  }) : JSON.stringify({
    seal_id: proofData.id,
    timestamp: proofData.ts,
    prev_hash: proofData.prev,
    cost_usd: proofData.cost,
    revenue_usd: proofData.revenue,
    margin_pct: proofData.margin,
    model: proofData.model,
    provider: proofData.provider,
  });

  const encoder = new TextEncoder();
  const hash = await crypto.subtle.digest('SHA-256', encoder.encode(hashable));
  const computed = Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');

  // Note: This is a simplified check. Full verification requires the complete
  // seal fields. The hash stored in proofData.hash was computed over more fields
  // than we carry in the compact proof. This verifies structural integrity only.
  return {
    valid: true,
    seal_id: proofData.id,
    sequence: proofData.seq,
    timestamp: proofData.ts,
    cost: proofData.cost,
    margin: proofData.margin,
    model: proofData.model,
    quality: proofData.quality,
    chain_linked: proofData.prev !== '0'.repeat(64),
    proof_hash: computed,
    stored_hash: proofData.hash,
  };
}

// ══════════════════════════════════════════════════════════════════════
// ═══════════════════════════════════════════════════════════════════════
// CONFIGURATION
// ═══════════════════════════════════════════════════════════════════════

const VERSION = '4.0.0-gold';

// ═══════════════════════════════════════════════════════════════════
// IN-MEMORY CACHES — Replace hot-path KV writes with Worker global memory
// Worker isolates persist global scope across requests (minutes to hours).
// This eliminates KV put() calls on every request, keeping us well under
// the free-tier 1,000 writes/day limit. Data here is ephemeral — that's
// fine because the source of truth is always Supabase.
// ═══════════════════════════════════════════════════════════════════

// Budget in-flight reservations (was: KV_CACHE budget:inflight:*)
// Key: "orgId:costCenter" → { amount: number, updated: number }
// Auto-expires entries older than 120s on read
const _budgetInflight = new Map();

function getBudgetInflight(orgId, costCenter) {
  const key = `${orgId}:${costCenter}`;
  const entry = _budgetInflight.get(key);
  if (!entry) return 0;
  // Auto-expire after 120s (same TTL as the old KV pattern)
  if (Date.now() - entry.updated > 120000) {
    _budgetInflight.delete(key);
    return 0;
  }
  return entry.amount;
}

function setBudgetInflight(orgId, costCenter, amount) {
  const key = `${orgId}:${costCenter}`;
  _budgetInflight.set(key, { amount, updated: Date.now() });
  // Prevent unbounded growth: prune entries older than 5 min every 100 writes
  if (_budgetInflight.size > 100) {
    const cutoff = Date.now() - 300000;
    for (const [k, v] of _budgetInflight) {
      if (v.updated < cutoff) _budgetInflight.delete(k);
    }
  }
}

// ═══════════════════════════════════════════════════════════════════
// SAVINGS COUNTER — in-memory tracker (Task 2.3)
// Key: orgId → { total_savings: number, since_date: ISO, updated: number }
// ═══════════════════════════════════════════════════════════════════
const _savingsCounter = new Map();

function getSavingsTotal(orgId) {
  const entry = _savingsCounter.get(orgId);
  if (!entry) return { total_savings: 0, since_date: new Date().toISOString() };
  return {
    total_savings: Math.round(entry.amount * 100) / 100,
    since_date: entry.since_date
  };
}

function incrementSavings(orgId, amount) {
  const existing = _savingsCounter.get(orgId) || {
    amount: 0,
    since_date: new Date().toISOString(),
    updated: Date.now()
  };
  existing.amount += amount;
  existing.updated = Date.now();
  _savingsCounter.set(orgId, existing);
}

// Provider latency tracking (was: CACHE provider_latency:*)
// Key: provider name → { total_ms, count, avg_ms, last_updated }
const _providerLatency = new Map();

function getProviderLatency(provider) {
  return _providerLatency.get(provider) || null;
}

function updateProviderLatency(provider, elapsedMs) {
  const existing = _providerLatency.get(provider) || { total_ms: 0, count: 0 };
  existing.total_ms += elapsedMs;
  existing.count += 1;
  existing.avg_ms = Math.round(existing.total_ms / existing.count);
  existing.last_updated = new Date().toISOString();
  _providerLatency.set(provider, existing);
}

// ═══════════════════════════════════════════════════════════════════
// SPRINT 2: ENHANCED SIGNAL EXTRACTION — in-memory trackers
// Retry loop detection, burst detection, session tracking
// Same pattern as KV fix: Worker global Maps with auto-expiry
// ═══════════════════════════════════════════════════════════════════

// Retry loop tracker: detects same prompt hash repeated within a window
// Key: "agentId:promptHash" → [timestamp, timestamp, ...]
const _retryTracker = new Map();
const RETRY_WINDOW = 60 * 1000; // 60 seconds
const RETRY_THRESHOLD = 3; // 3 identical prompts = likely retry

function checkRetryLoop(agentId, promptHash) {
  if (!promptHash || promptHash === '0'.repeat(64)) return { isRetry: false, retryCount: 0 };
  const key = `${agentId}:${promptHash}`;
  const now = Date.now();
  const calls = (_retryTracker.get(key) || []).filter(t => now - t < RETRY_WINDOW);
  calls.push(now);
  _retryTracker.set(key, calls);
  // Prune old keys periodically
  if (_retryTracker.size > 500) {
    for (const [k, v] of _retryTracker) {
      if (v.length === 0 || now - v[v.length - 1] > RETRY_WINDOW * 2) _retryTracker.delete(k);
    }
  }
  return {
    isRetry: calls.length >= RETRY_THRESHOLD,
    retryCount: calls.length,
    severity: calls.length > 20 ? 'critical' : calls.length > 10 ? 'high' : calls.length >= RETRY_THRESHOLD ? 'medium' : null,
  };
}

// Burst detection tracker: detects high call frequency from a single agent
// Key: agentId → [timestamp, timestamp, ...]
const _burstTracker = new Map();
const BURST_WINDOW = 60 * 1000; // 60 seconds
const BURST_THRESHOLD = 50; // 50 calls in 60s = burst

function checkBurst(agentId) {
  const key = `burst:${agentId}`;
  const now = Date.now();
  const calls = (_burstTracker.get(key) || []).filter(t => now - t < BURST_WINDOW);
  calls.push(now);
  _burstTracker.set(key, calls);
  if (_burstTracker.size > 200) {
    for (const [k, v] of _burstTracker) {
      if (v.length === 0 || now - v[v.length - 1] > BURST_WINDOW * 2) _burstTracker.delete(k);
    }
  }
  return {
    isBurst: calls.length >= BURST_THRESHOLD,
    burstCount: calls.length,
  };
}

// Session tracker: groups related calls by agent within a time window
// Key: agentId → { sessionId, lastCallTime, callCount, totalCost }
const _sessionTracker = new Map();
const SESSION_TIMEOUT = 30 * 60 * 1000; // 30 minutes between calls = new session

function getOrCreateSession(agentId, costCenter) {
  const key = agentId || costCenter || 'anonymous';
  const now = Date.now();
  const existing = _sessionTracker.get(key);
  if (existing && (now - existing.lastCallTime) < SESSION_TIMEOUT) {
    existing.lastCallTime = now;
    existing.callCount += 1;
    _sessionTracker.set(key, existing);
    return existing;
  }
  // New session
  const sessionId = `sess_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
  const session = { sessionId, startedAt: now, lastCallTime: now, callCount: 1, totalCost: 0, agentId: key };
  _sessionTracker.set(key, session);
  // Prune old sessions
  if (_sessionTracker.size > 300) {
    const cutoff = now - SESSION_TIMEOUT * 2;
    for (const [k, v] of _sessionTracker) {
      if (v.lastCallTime < cutoff) _sessionTracker.delete(k);
    }
  }
  return session;
}

function addSessionCost(agentId, costCenter, cost) {
  const key = agentId || costCenter || 'anonymous';
  const session = _sessionTracker.get(key);
  if (session && cost > 0) {
    session.totalCost += cost;
    _sessionTracker.set(key, session);
  }
}

// ═══════════════════════════════════════════════════════════════════
// ITEM 2: RATE LIMITING ON MANAGEMENT ENDPOINTS
// ═══════════════════════════════════════════════════════════════════

/**
 * Rate limit check using KV storage
 * @param {object} env - Environment with KV_CACHE
 * @param {string} key - Unique key (e.g., "org:orgId" or "ip:clientIP")
 * @param {number} limit - Max requests per window
 * @param {number} windowSec - Time window in seconds (default 60)
 * @returns {Promise<Response|null>} Response with 429 if limited, null if allowed
 */
async function rateLimit(env, key, limit, windowSec = 60) {
  const now = Math.floor(Date.now() / 1000);
  const window = Math.floor(now / windowSec);
  const rlKey = `rl:${key}:${window}`;
  try {
    const count = parseInt(await env.KV_CACHE.get(rlKey) || '0');
    if (count >= limit) {
      return new Response(JSON.stringify({ error: 'Rate limit exceeded' }), {
        status: 429,
        headers: { 'Content-Type': 'application/json', 'Retry-After': String(windowSec - (now % windowSec)) }
      });
    }
    await env.KV_CACHE.put(rlKey, String(count + 1), { expirationTtl: windowSec * 2 });
  } catch(e) {
    // KV failure = skip rate limit, proceed (fail open)
    console.warn(`[WARN] Rate limit KV failure: ${e.message}`);
  }
  return null;
}

// ═══════════════════════════════════════════════════════════════════
// ITEM 3: KV ARCHITECTURE CLEANUP - Read-Through Cache + Batched Counters
// ═══════════════════════════════════════════════════════════════════

/**
 * Read-through cache: check KV, fall back to Supabase query, cache result
 * @param {object} env - Environment with KV_CACHE
 * @param {object} ctx - Request context for waitUntil
 * @param {string} kvKey - Cache key in KV
 * @param {Function} supabaseQueryFn - Async function that fetches from Supabase
 * @param {number} ttlSec - Cache TTL in seconds (default 300)
 * @returns {Promise<any>} Cached or fresh data
 */
async function cachedRead(env, ctx, kvKey, supabaseQueryFn, ttlSec = 300) {
  try {
    const cached = await env.KV_CACHE.get(kvKey);
    if (cached) return JSON.parse(cached);
  } catch(e) {
    // KV read failed, fall through to Supabase
  }

  const data = await supabaseQueryFn();
  if (data && ctx) {
    ctx.waitUntil(env.KV_CACHE.put(kvKey, JSON.stringify(data), { expirationTtl: ttlSec }).catch(() => {}));
  }
  return data;
}

/**
 * Batched cost accumulation — accumulate costs in memory, flush to Supabase + KV periodically
 */
const pendingCosts = {};
let costFlushCount = 0;

/**
 * Accumulate a cost to be flushed later
 * @param {string} orgId - Organization ID
 * @param {string} customerId - Customer ID
 * @param {number} cost - Cost amount in USD
 */
function accumulateCost(orgId, customerId, cost) {
  const month = new Date().toISOString().slice(0, 7);
  const key = `${orgId}:${customerId}:${month}`;
  pendingCosts[key] = (pendingCosts[key] || 0) + cost;
  costFlushCount++;
}

/**
 * Flush pending costs to Supabase and KV
 * @param {object} env - Environment with SUPABASE_URL, SUPABASE_KEY, KV_CACHE
 * @returns {Promise<void>}
 */
async function flushPendingCosts(env) {
  const batch = { ...pendingCosts };
  for (const k of Object.keys(batch)) delete pendingCosts[k];
  costFlushCount = 0;

  for (const [key, amount] of Object.entries(batch)) {
    const [orgId, customerId, month] = key.split(':');
    try {
      // Update Supabase via RPC
      const supabaseResp = await fetch(`${env.SUPABASE_URL}/rest/v1/rpc/increment_cost`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'apikey': env.SUPABASE_KEY,
          'Authorization': `Bearer ${env.SUPABASE_KEY}`
        },
        body: JSON.stringify({
          p_org_id: orgId,
          p_customer_id: customerId,
          p_month: month,
          p_amount: amount
        })
      });

      if (!supabaseResp.ok) {
        throw new Error(`Supabase RPC failed: ${supabaseResp.status}`);
      }

      // Update KV cache with current spend
      const kvKey = `spend:${key}`;
      const current = parseFloat(await env.KV_CACHE.get(kvKey) || '0');
      await env.KV_CACHE.put(kvKey, String(current + amount), { expirationTtl: 86400 * 35 });
    } catch(e) {
      // On failure, re-accumulate for next flush
      console.error(`[ERROR] Failed to flush cost ${key}: ${e.message}`);
      pendingCosts[key] = (pendingCosts[key] || 0) + amount;
    }
  }
}

// Compute prompt hash (SHA-256 of messages/prompt content)
// For retry loop detection — NEVER stores prompt content, only hash
async function computePromptHash(bodyText) {
  try {
    const parsed = JSON.parse(bodyText);
    const content = JSON.stringify(parsed.messages || parsed.prompt || '');
    const hash = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(content));
    return Array.from(new Uint8Array(hash)).map(b => b.toString(16).padStart(2, '0')).join('');
  } catch (e) {
    return null;
  }
}

// Extract request complexity signals from parsed body
function extractComplexitySignals(bodyText) {
  try {
    const parsed = JSON.parse(bodyText);
    return {
      isStreaming: !!parsed.stream,
      hasTools: !!(parsed.tools && parsed.tools.length > 0),
      toolCount: parsed.tools?.length || 0,
      hasSystemPrompt: !!(parsed.messages?.find(m => m.role === 'system')),
      messageCount: parsed.messages?.length || 0,
      maxTokens: parsed.max_tokens || null,
      temperature: parsed.temperature ?? null,
      timeOfDay: new Date().getUTCHours(),
      dayOfWeek: new Date().getUTCDay(),
    };
  } catch (e) {
    return {
      isStreaming: false, hasTools: false, toolCount: 0,
      hasSystemPrompt: false, messageCount: 0, maxTokens: null,
      temperature: null, timeOfDay: new Date().getUTCHours(),
      dayOfWeek: new Date().getUTCDay(),
    };
  }
}

/**
 * Get configuration from environment with defaults
 * All previously hardcoded values are now configurable
 */
function getConfig(env) {
  return {
    // API Base URLs
    openaiApiBase: env.OPENAI_API_BASE || 'https://api.openai.com',
    anthropicApiBase: env.ANTHROPIC_API_BASE || 'https://api.anthropic.com',
    googleApiBase: env.GOOGLE_API_BASE || 'https://generativelanguage.googleapis.com',
    azureApiBase: env.AZURE_API_BASE || 'https://{resource}.openai.azure.com',
    bedrockApiBase: env.BEDROCK_API_BASE || 'https://bedrock-runtime.{region}.amazonaws.com',

    // Session & Security
    sessionTTL: parseInt(env.SESSION_TTL) || 86400, // 24 hours
    jwtExpiresIn: parseInt(env.JWT_EXPIRES_IN) || 3600, // 1 hour
    maxRuleDepth: parseInt(env.MAX_RULE_DEPTH) || 10,

    // Data Retention
    retentionDays: parseInt(env.RETENTION_DAYS) || 2555, // 7 years
    auditLogRetentionDays: parseInt(env.AUDIT_LOG_RETENTION_DAYS) || 2555,

    // Rate Limits
    defaultRateLimit: parseInt(env.DEFAULT_RATE_LIMIT) || 100,
    authenticatedRateLimit: parseInt(env.AUTHENTICATED_RATE_LIMIT) || 1000,
    heavyEndpointRateLimit: parseInt(env.HEAVY_ENDPOINT_RATE_LIMIT) || 10,
    proxyRateLimit: parseInt(env.PROXY_RATE_LIMIT) || 500,

    // Timeouts
    requestTimeout: parseInt(env.REQUEST_TIMEOUT) || 30000,
    proxyTimeout: parseInt(env.PROXY_TIMEOUT) || 120000,

    // Feature Flags
    enableDemoMode: env.ENABLE_DEMO_MODE === 'true',
    allowQueryOrgId: env.ALLOW_QUERY_ORG_ID === 'true',
    enableDebugLogs: env.ENABLE_DEBUG_LOGS === 'true',

    // Default Cost Center
    defaultCostCenter: env.DEFAULT_COST_CENTER || 'unallocated'
  };
}

