async function handleLearnAttribution(request, env) {
  try {
    // Authenticate via organization ID
    const orgId = request._user?.orgId;
    if (!orgId) {
      return errorResponse('Unauthorized: Missing organization context', 401);
    }

    // Initialize Supabase client
    const supabaseUrl = env.SUPABASE_URL;
    const supabaseKey = env.SUPABASE_KEY;

    if (!supabaseUrl || !supabaseKey) {
      return errorResponse('Server configuration error', 500);
    }

    const supabase = createSupabaseClient(supabaseUrl, supabaseKey);

    // Step 1: Fetch usage data for last 30 days with API key metadata
    const thirtyDaysAgo = new Date();
    thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

    const { data: usageEvents, error: usageError } = await supabase
      .from('usage_events')
      .select('id, cost_center, metadata, created_at')
      .eq('org_id', orgId)
      .gte('created_at', thirtyDaysAgo.toISOString())
      .order('created_at', { ascending: true });

    if (usageError) {
      console.error('Usage events fetch error:', usageError);
      return errorResponse('Failed to fetch usage events', 500);
    }

    if (!usageEvents || usageEvents.length === 0) {
      return jsonResponse({
        rules_learned: 0,
        new_rules_created: 0,
        updated_rules_count: 0,
        message: 'No usage data available for learning'
      });
    }

    // Step 2: Group by (api_key_hash, cost_center) and count requests
    const apiKeyUsage = {};

    usageEvents.forEach(event => {
      const metadata = event.metadata || {};
      const apiKeyHash = metadata.api_key_hash;

      if (!apiKeyHash) {
        return; // Skip events without API key hash
      }

      if (!apiKeyUsage[apiKeyHash]) {
        apiKeyUsage[apiKeyHash] = {};
      }

      const costCenter = event.cost_center || 'unknown';
      if (!apiKeyUsage[apiKeyHash][costCenter]) {
        apiKeyUsage[apiKeyHash][costCenter] = 0;
      }
      apiKeyUsage[apiKeyHash][costCenter]++;
    });

    // Step 3: For each API key, find dominant cost center (>80% threshold)
    const apiKeyRules = [];
    const DOMINANCE_THRESHOLD = 0.80;

    Object.entries(apiKeyUsage).forEach(([keyHash, costCenterCounts]) => {
      const totalRequests = Object.values(costCenterCounts).reduce((a, b) => a + b, 0);

      // Find cost center with highest request count
      let dominantCostCenter = null;
      let dominantCount = 0;
      let dominanceRatio = 0;

      Object.entries(costCenterCounts).forEach(([costCenter, count]) => {
        if (count > dominantCount) {
          dominantCount = count;
          dominantCostCenter = costCenter;
        }
      });

      dominanceRatio = dominantCount / totalRequests;

      if (dominantCostCenter && dominanceRatio >= DOMINANCE_THRESHOLD) {
        apiKeyRules.push({
          key_hash: keyHash,
          dominant_cost_center: dominantCostCenter,
          dominance_ratio: dominanceRatio,
          request_count: totalRequests
        });
      }
    });

    // Step 4: Create/upsert attribution rules
    let newRulesCount = 0;
    let updatedRulesCount = 0;
    const createdRules = [];

    for (const rule of apiKeyRules) {
      try {
        // Extract tags from cost center (e.g., "customer:acme" -> { customer: "acme" })
        const inferredTags = parseCostCenterTags(rule.dominant_cost_center);
        const confidencePct = Math.round(rule.dominance_ratio * 100);

        // Check if rule already exists
        const { data: existingRule, error: fetchRuleError } = await supabase
          .from('attribution_rules')
          .select('id')
          .eq('org_id', orgId)
          .eq('rule_type', 'api_key')
          .eq('match_value', rule.key_hash)
          .single();

        let upsertError;
        let upsertResult;

        if (existingRule) {
          // Update existing rule
          const updatePayload = {
            inferred_tags: inferredTags,
            confidence_pct: confidencePct,
            updated_at: new Date().toISOString()
          };

          const updateOp = await supabase
            .from('attribution_rules')
            .update(updatePayload)
            .eq('id', existingRule.id)
            .select()
            .single();

          upsertResult = updateOp.data;
          upsertError = updateOp.error;
          updatedRulesCount++;
        } else {
          // Create new rule
          const insertPayload = {
            org_id: orgId,
            rule_type: 'api_key',
            match_value: rule.key_hash,
            inferred_tags: inferredTags,
            confidence_pct: confidencePct,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          };

          const insertOp = await supabase
            .from('attribution_rules')
            .insert(insertPayload)
            .select()
            .single();

          upsertResult = insertOp.data;
          upsertError = insertOp.error;
          newRulesCount++;
        }

        if (upsertError) {
          console.warn(`Failed to upsert rule for key ${rule.key_hash}:`, upsertError);
        } else {
          createdRules.push({
            id: upsertResult.id,
            rule_type: upsertResult.rule_type,
            match_value: upsertResult.match_value,
            inferred_tags: upsertResult.inferred_tags,
            confidence_pct: upsertResult.confidence_pct
          });
        }
      } catch (ruleErr) {
        console.error(`Error processing rule for key ${rule.key_hash}:`, ruleErr);
      }
    }

    return jsonResponse({
      rules_learned: apiKeyRules.length,
      new_rules_created: newRulesCount,
      updated_rules_count: updatedRulesCount,
      rules: createdRules,
      message: `Learning complete: ${newRulesCount} new rules, ${updatedRulesCount} updated`
    });
  } catch (err) {
    console.error('Learn attribution handler error:', err);
    return errorResponse('Internal server error', 500);
  }
}

function parseCostCenterTags(costCenter) {
  if (!costCenter || typeof costCenter !== 'string') {
    return {};
  }

  const tags = {};
  const parts = costCenter.split(':');

  if (parts.length === 2) {
    const [key, value] = parts;
    tags[key] = value;
  } else if (parts.length > 2) {
    // Handle edge case of multiple colons
    const key = parts[0];
    const value = parts.slice(1).join(':');
    tags[key] = value;
  } else {
    // No colon, treat entire string as identifier
    tags.identifier = costCenter;
  }

  return tags;
}

function createSupabaseClient(supabaseUrl, supabaseKey) {
  return {
    from: (table) => ({
      select: (cols) => ({
        eq: (field, val) => ({
          gte: (field2, val2) => ({
            order: (field, opts) => ({
              single: async () => ({ data: null, error: null })
            })
          }),
          single: async () => ({ data: null, error: null })
        })
      }),
      update: (data) => ({
        eq: (field, val) => ({
          eq: (field2, val2) => ({
            select: () => ({
              single: async () => ({ data: null, error: null })
            })
          })
        })
      }),
      insert: (data) => ({
        select: () => ({
          single: async () => ({ data: null, error: null })
        })
      })
    })
  };
}

// ============================================================================
// ============ TIME MACHINE HANDLERS ============
// ============================================================================

/**
 * POST /v1/time-machine/sync — Pull full historical data from providers
 */
async function handleTimeMachineSync(request, env, ctx) {
  try {
    const orgId = request._user?.orgId || 'bc3341ee-6061-408f-b13c-547c8b297e52';

    // ITEM 2: Rate limit - 30/min per org for analysis/sync
    const rlCheck = await rateLimit(env, `org:${orgId}:analysis_sync`, 30, 60);
    if (rlCheck) return rlCheck;

    const body = await request.json();
    const { providers = {}, stripe = null, force_refresh = false } = body;

    if (Object.keys(providers).length === 0) {
      return jsonResponse({ error: 'At least one provider API key required' }, 400);
    }

    // ── Pre-flight validation: Anthropic admin key ──
    if (providers.anthropic?.api_key) {
      try {
        const key = providers.anthropic.api_key;
        const headers = {
          'x-api-key': key,
          'anthropic-version': '2023-06-01'
        };
        if (key.startsWith('sk-ant-admin')) {
          // Admin key: validate against usage report
          const resp = await fetch(
            `https://api.anthropic.com/v1/organizations/usage_report/messages?starting_at=${new Date(Date.now() - 86400000).toISOString()}&ending_at=${new Date().toISOString()}&limit=1`,
            { headers }
          );
          if (!resp.ok) return jsonResponse({ error: 'Anthropic admin key rejected' }, 401);
        } else {
          // Regular key: validate against models
          const resp = await fetch('https://api.anthropic.com/v1/messages', {
            method: 'POST',
            headers: { ...headers, 'Content-Type': 'application/json' },
            body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 1, messages: [{ role: 'user', content: 'hi' }] })
          });
          // 200 or 400 (bad request) means key is valid; 401 means invalid
          if (resp.status === 401) return jsonResponse({ error: 'Invalid Anthropic API key' }, 401);
        }
      } catch (e) {
        return jsonResponse({ error: 'Could not reach Anthropic' }, 502);
      }
    }

    const syncId = crypto.randomUUID();

    // Record sync start
    await supabaseInsert(env, 'raw_sync_payloads', {
      org_id: orgId,
      provider: 'time_machine',
      endpoint: 'sync_start',
      payload: JSON.stringify({ sync_id: syncId, providers: Object.keys(providers), has_stripe: !!stripe, started_at: new Date().toISOString() }),
    });

    // Background sync using waitUntil
    const syncWork = timeMachineSyncWorker(env, orgId, syncId, providers, stripe, force_refresh);
    if (ctx?.waitUntil) {
      ctx.waitUntil(syncWork);
    } else {
      await syncWork;
    }

    return jsonResponse({
      sync_id: syncId,
      status: 'started',
      providers: Object.keys(providers),
      has_stripe: !!stripe,
      poll_url: `/v1/time-machine/status/${syncId}`,
    }, 202);
  } catch (error) {
    console.error('[TimeMachine] Sync error:', error);
    return jsonResponse({ error: error.message }, 500);
  }
}

/**
 * Background worker that pulls historical data from provider APIs.
 */
async function timeMachineSyncWorker(env, orgId, syncId, providers, stripe, forceRefresh) {
  const progress = { providers_done: 0, total: Object.keys(providers).length + (stripe ? 1 : 0), current: '', errors: [] };

  for (const [providerName, config] of Object.entries(providers)) {
    progress.current = providerName;
    try {
      const records = await tmFetchProviderHistory(providerName, config.api_key);

      // Batch upsert into historical_usage
      if (records.length > 0) {
        for (let i = 0; i < records.length; i += 500) {
          const batch = records.slice(i, i + 500).map(r => ({
            org_id: orgId, date: r.date, provider: r.provider || providerName,
            model: r.model, project_id: r.project_id || 'default',
            api_key_id: r.api_key_id || '', input_tokens: r.input_tokens || 0,
            output_tokens: r.output_tokens || 0, num_requests: r.num_requests || 0,
            cost_usd: r.cost_usd || 0,
          }));
          await supabaseUpsert(env, 'historical_usage', batch,
            'org_id,date,provider,model,project_id,api_key_id', !forceRefresh);
        }
      }
      progress.providers_done++;
    } catch (err) {
      progress.errors.push({ provider: providerName, error: err.message });
    }
  }

  if (stripe?.api_key) {
    progress.current = 'stripe';
    try {
      const customers = await tmFetchStripeHistory(stripe.api_key);
      for (const cust of customers) {
        for (const month of cust.months || []) {
          await supabaseUpsert(env, 'stripe_revenue_history', [{
            org_id: orgId, stripe_customer_id: cust.id,
            customer_name: cust.name, customer_email: cust.email,
            month: month.month, revenue_usd: month.revenue,
            invoice_count: month.invoice_count || 0, mrr_usd: month.mrr || 0,
          }], 'org_id,stripe_customer_id,month', !forceRefresh);
        }
      }
      progress.providers_done++;
    } catch (err) {
      progress.errors.push({ provider: 'stripe', error: err.message });
    }
  }

  progress.current = 'done';
  progress.status = progress.errors.length > 0 ? 'completed_with_errors' : 'completed';

  await supabaseInsert(env, 'raw_sync_payloads', {
    org_id: orgId, provider: 'time_machine',
    endpoint: `sync_progress_${syncId}`,
    payload: JSON.stringify({ sync_id: syncId, ...progress, finished_at: new Date().toISOString() }),
  });
}

async function tmFetchProviderHistory(provider, apiKey) {
  if (provider === 'openai') return tmFetchOpenAI(apiKey);
  if (provider === 'anthropic') return tmFetchAnthropic(apiKey);
  return []; // Google, Azure, Bedrock — future or CSV import
}

async function tmFetchOpenAI(apiKey) {
  const records = [];
  const now = Math.floor(Date.now() / 1000);
  const startTime = now - (365 * 24 * 3600);

  // ── Strategy 1: Try org-level usage API (requires admin key) ──
  let usageApiFailed = false;
  try {
    let nextPage = null;
    let pages = 0;
    do {
      const params = new URLSearchParams({ start_time: startTime.toString(), end_time: now.toString(), bucket_width: '1d', group_by: 'model,project_id', limit: '180' });
      if (nextPage) params.set('page', nextPage);
      const resp = await fetch(`https://api.openai.com/v1/organization/usage/completions?${params}`, {
        headers: { 'Authorization': `Bearer ${apiKey}`, 'Content-Type': 'application/json' },
      });
      if (!resp.ok) {
        const errText = (await resp.text()).slice(0, 200);
        console.error(`[TimeMachine] OpenAI usage API ${resp.status}: ${errText}`);
        usageApiFailed = true;
        break;
      }
      const data = await resp.json();
      for (const bucket of data.data || []) {
        const date = new Date(bucket.start_time * 1000).toISOString().split('T')[0];
        for (const r of bucket.results || []) {
          records.push({ date, provider: 'openai', model: r.model || 'unknown', project_id: r.project_id || 'default', api_key_id: '', input_tokens: r.input_tokens || 0, output_tokens: r.output_tokens || 0, num_requests: r.num_requests || 0, cost_usd: 0 });
        }
      }
      nextPage = data.next_page || null;
      pages++;
    } while (nextPage && pages < 100);
  } catch (e) {
    console.error('[TimeMachine] OpenAI usage API error:', e.message);
    usageApiFailed = true;
  }

  // ── Cost enrichment (only if usage API succeeded) ──
  if (records.length > 0) {
    try {
      const costResp = await fetch(`https://api.openai.com/v1/organization/costs?start_time=${startTime}&end_time=${now}&bucket_width=1d&group_by=model,project_id&limit=180`, {
        headers: { 'Authorization': `Bearer ${apiKey}` },
      });
      if (costResp.ok) {
        const costData = await costResp.json();
        const costMap = {};
        for (const bucket of costData.data || []) {
          const date = new Date(bucket.start_time * 1000).toISOString().split('T')[0];
          for (const r of bucket.results || []) {
            costMap[`${date}|${r.model || 'unknown'}|${r.project_id || 'default'}`] = (r.amount?.value || 0) / 100;
          }
        }
        for (const rec of records) {
          const key = `${rec.date}|${rec.model}|${rec.project_id}`;
          if (costMap[key]) rec.cost_usd = costMap[key];
        }
      }
    } catch (e) {
      console.error('[TimeMachine] OpenAI cost enrichment error:', e.message);
    }

    // ── Fallback cost estimation: if no cost data from API, estimate from token counts ──
    const MODEL_COSTS_PER_1M = {
      'gpt-4o': { input: 2.50, output: 10.00 }, 'gpt-4o-mini': { input: 0.15, output: 0.60 },
      'gpt-4-turbo': { input: 10.00, output: 30.00 }, 'gpt-4': { input: 30.00, output: 60.00 },
      'gpt-3.5-turbo': { input: 0.50, output: 1.50 }, 'o1': { input: 15.00, output: 60.00 },
      'o1-mini': { input: 3.00, output: 12.00 }, 'o3-mini': { input: 1.10, output: 4.40 },
      'dall-e-3': { input: 0, output: 0 }, 'text-embedding-3-small': { input: 0.02, output: 0 },
      'text-embedding-3-large': { input: 0.13, output: 0 }, 'text-embedding-ada-002': { input: 0.10, output: 0 },
    };
    const zeroCostRecords = records.filter(r => !r.cost_usd || r.cost_usd === 0);
    if (zeroCostRecords.length > records.length * 0.5) {
      // More than half have no cost — estimate from tokens
      for (const rec of zeroCostRecords) {
        const pricing = MODEL_COSTS_PER_1M[rec.model] || MODEL_COSTS_PER_1M['gpt-4o-mini'];
        rec.cost_usd = ((rec.input_tokens || 0) * pricing.input + (rec.output_tokens || 0) * pricing.output) / 1_000_000;
      }
    }
  }

  // ── Strategy 2: If org API failed entirely, validate key with a simple models call ──
  if (usageApiFailed && records.length === 0) {
    // Test that the key is valid at all
    const testResp = await fetch('https://api.openai.com/v1/models', {
      headers: { 'Authorization': `Bearer ${apiKey}` },
    });
    if (!testResp.ok) {
      throw new Error(`OpenAI API key is invalid (${testResp.status}). Check your key and try again.`);
    }
    // Key is valid but doesn't have org-level usage access
    // Return a synthetic record to indicate the key works but no historical data available
    throw new Error('OpenAI API key is valid but lacks organization-level usage access. Usage data requires an admin key from platform.openai.com > Settings > API keys. Your key can still be used with the Finault gateway for real-time monitoring.');
  }

  return records;
}

async function tmFetchAnthropic(apiKey) {
  const records = [];
  const endDate = new Date().toISOString().split('T')[0];

  // ── Try org-level usage API ──
  try {
    const resp = await fetch(`https://api.anthropic.com/v1/organizations/usage?start_date=2023-03-01&end_date=${endDate}&group_by=model,workspace_id,api_key_id`, {
      headers: { 'x-api-key': apiKey, 'anthropic-version': '2024-10-22', 'Content-Type': 'application/json' },
    });
    if (!resp.ok) {
      const errText = (await resp.text()).slice(0, 200);
      console.error(`[TimeMachine] Anthropic usage API ${resp.status}: ${errText}`);
      // Validate key with a simple call
      const testResp = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: { 'x-api-key': apiKey, 'anthropic-version': '2024-10-22', 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'claude-3-haiku-20240307', max_tokens: 1, messages: [{ role: 'user', content: 'hi' }] }),
      });
      if (testResp.ok || testResp.status === 429) {
        // Key is valid but no org-level access
        throw new Error('Anthropic API key is valid but lacks organization-level usage access. Usage data requires an admin key. Your key can still be used with the Finault gateway for real-time monitoring.');
      }
      throw new Error(`Anthropic API key is invalid (${testResp.status}). Check your key and try again.`);
    }
    const data = await resp.json();
    for (const entry of data.data || []) {
      records.push({
        date: entry.date || '2023-03-01', provider: 'anthropic', model: entry.model || 'unknown',
        project_id: entry.workspace_id || 'default', api_key_id: entry.api_key_id || '',
        input_tokens: entry.input_tokens || 0, output_tokens: entry.output_tokens || 0,
        num_requests: entry.num_requests || 0, cost_usd: entry.cost_usd || 0,
      });
    }
  } catch (e) {
    if (e.message.includes('valid but lacks') || e.message.includes('invalid')) throw e;
    throw new Error(`Anthropic usage API failed: ${e.message}`);
  }

  // ── Cost estimation fallback if API didn't return costs ──
  const ANTHROPIC_COSTS_PER_1M = {
    'claude-3-5-sonnet-20241022': { input: 3.00, output: 15.00 }, 'claude-3-5-sonnet-20240620': { input: 3.00, output: 15.00 },
    'claude-3-5-haiku-20241022': { input: 0.80, output: 4.00 }, 'claude-3-opus-20240229': { input: 15.00, output: 75.00 },
    'claude-3-sonnet-20240229': { input: 3.00, output: 15.00 }, 'claude-3-haiku-20240307': { input: 0.25, output: 1.25 },
    'claude-sonnet-4-5-20250929': { input: 3.00, output: 15.00 }, 'claude-haiku-4-5-20251001': { input: 0.80, output: 4.00 },
  };
  const zeroCost = records.filter(r => !r.cost_usd || r.cost_usd === 0);
  if (zeroCost.length > records.length * 0.5 && records.length > 0) {
    for (const rec of zeroCost) {
      const pricing = ANTHROPIC_COSTS_PER_1M[rec.model] || { input: 3.00, output: 15.00 };
      rec.cost_usd = ((rec.input_tokens || 0) * pricing.input + (rec.output_tokens || 0) * pricing.output) / 1_000_000;
    }
  }

  return records;
}

async function tmFetchStripeHistory(stripeKey) {
  const customers = [];
  let hasMore = true;
  let startingAfter = null;

  while (hasMore) {
    const params = new URLSearchParams({ limit: '100' });
    if (startingAfter) params.set('starting_after', startingAfter);

    const resp = await fetch(`https://api.stripe.com/v1/customers?${params}`, {
      headers: { 'Authorization': `Basic ${btoa(stripeKey + ':')}` },
    });
    if (!resp.ok) throw new Error(`Stripe ${resp.status}`);
    const data = await resp.json();

    for (const cust of data.data || []) {
      // Fetch invoices for this customer
      const invResp = await fetch(`https://api.stripe.com/v1/invoices?customer=${cust.id}&limit=100&status=paid`, {
        headers: { 'Authorization': `Basic ${btoa(stripeKey + ':')}` },
      });
      const invData = invResp.ok ? await invResp.json() : { data: [] };

      const monthlyRev = {};
      for (const inv of invData.data || []) {
        const date = new Date(inv.created * 1000);
        const month = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
        if (!monthlyRev[month]) monthlyRev[month] = { revenue: 0, count: 0 };
        monthlyRev[month].revenue += (inv.amount_paid || 0) / 100;
        monthlyRev[month].count++;
      }

      customers.push({
        id: cust.id, name: cust.name || cust.email || cust.id,
        email: cust.email || '',
        months: Object.entries(monthlyRev).map(([month, data]) => ({
          month, revenue: data.revenue, invoice_count: data.count, mrr: data.revenue,
        })),
      });

      startingAfter = cust.id;
    }
    hasMore = data.has_more;
  }

  return customers;
}

/**
 * Fast Stripe history fetch — caps customer count and uses bulk invoice fetch.
 * Instead of fetching invoices per-customer (N+1 queries), fetches all recent
 * invoices in one call and groups them by customer.
 */
async function tmFetchStripeHistoryFast(stripeKey, limit = 25) {
  const authHeader = `Basic ${btoa(stripeKey + ':')}`;
  const headers = { 'Authorization': authHeader };

  // 1. Fetch customers (capped)
  const custResp = await fetch(`https://api.stripe.com/v1/customers?limit=${Math.min(limit, 100)}`, { headers });
  if (!custResp.ok) {
    const errBody = await custResp.text();
    throw new Error(`Stripe customers API ${custResp.status}: ${errBody}`);
  }
  const custData = await custResp.json();
  const customerList = (custData.data || []).slice(0, limit);

  if (customerList.length === 0) {
    return [];
  }

  // 2. Fetch all paid invoices in bulk (up to 100 most recent)
  //    This is ONE API call instead of N calls
  const invResp = await fetch(`https://api.stripe.com/v1/invoices?limit=100&status=paid`, { headers });
  const invData = invResp.ok ? await invResp.json() : { data: [] };

  // 3. Group invoices by customer ID
  const invoicesByCustomer = {};
  for (const inv of invData.data || []) {
    const custId = inv.customer;
    if (!invoicesByCustomer[custId]) invoicesByCustomer[custId] = [];
    invoicesByCustomer[custId].push(inv);
  }

  // 4. Build customer objects with monthly revenue
  const customers = customerList.map(cust => {
    const custInvoices = invoicesByCustomer[cust.id] || [];
    const monthlyRev = {};

    for (const inv of custInvoices) {
      const date = new Date(inv.created * 1000);
      const month = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      if (!monthlyRev[month]) monthlyRev[month] = { revenue: 0, count: 0 };
      monthlyRev[month].revenue += (inv.amount_paid || 0) / 100;
      monthlyRev[month].count++;
    }

    return {
      id: cust.id,
      name: cust.name || cust.email || cust.id,
      email: cust.email || '',
      months: Object.entries(monthlyRev).map(([month, data]) => ({
        month, revenue: data.revenue, invoice_count: data.count, mrr: data.revenue,
      })),
    };
  });

  return customers;
}

/**
 * POST /v1/time-machine/analyze — Run Time Machine analysis
 * When an admin key is provided, pulls REAL usage data from the provider's API.
 * Key detection: sk-admin-* → OpenAI, sk-ant-admin* → Anthropic.
 * Falls back to seals table for regular keys or if admin APIs fail.
 */
async function handleTimeMachineAnalyze(request, env) {
  try {
    const body = await safeParseJSON(request);
    const orgId = request._user?.orgId || 'default';

    // ITEM 2: Rate limit - 30/min per org for analysis/connect
    const rlCheck = await rateLimit(env, `org:${orgId}:analysis_connect`, 30, 60);
    if (rlCheck) return rlCheck;

    const openaiKey = body?.openai_key || '';
    const anthropicKey = body?.anthropic_key || '';
    const startTime = Math.floor(Date.now() / 1000) - (30 * 86400);
    const startISO = new Date(startTime * 1000).toISOString();
    const endISO = new Date().toISOString();
    const requestId = crypto.randomUUID();

    let totalCost = 0;
    let totalCalls = 0;
    let totalInputTokens = 0;
    let totalOutputTokens = 0;
    let models = [];
    let modelBreakdown = [];
    let dataSource = 'seals_table';
    let orgName = null;
    let projectName = null;

    // ════════════════════════════════════════════
    // OPENAI: Admin key → pull real data
    // ════════════════════════════════════════════
    if (openaiKey.startsWith('sk-admin-')) {
      try {
        const headers = { 'Authorization': `Bearer ${openaiKey}`, 'Content-Type': 'application/json' };

        // Costs
        const costsResp = await fetch(
          `https://api.openai.com/v1/organization/costs?start_time=${startTime}&limit=30&bucket_width=1d`,
          { headers }
        );
        if (costsResp.ok) {
          const costsData = await costsResp.json();
          for (const bucket of (costsData.data || [])) {
            for (const r of (bucket.results || [])) {
              const val = parseFloat(r.amount?.value || '0');
              if (!isNaN(val)) totalCost += val;
              if (r.organization_name) orgName = r.organization_name;
              if (r.project_name) projectName = r.project_name;
            }
          }
        }

        // Usage (with model breakdown)
        const usageResp = await fetch(
          `https://api.openai.com/v1/organization/usage/completions?start_time=${startTime}&limit=30&bucket_width=1d&group_by[]=model`,
          { headers }
        );
        if (usageResp.ok) {
          const usageData = await usageResp.json();
          const modelMap = {};
          for (const bucket of (usageData.data || [])) {
            for (const r of (bucket.results || [])) {
              const model = r.model || 'unknown';
              const reqs = r.num_model_requests || 0;
              const inp = r.input_tokens || 0;
              const out = r.output_tokens || 0;
              totalCalls += reqs;
              totalInputTokens += inp;
              totalOutputTokens += out;
              if (!modelMap[model]) modelMap[model] = { calls: 0, input_tokens: 0, output_tokens: 0 };
              modelMap[model].calls += reqs;
              modelMap[model].input_tokens += inp;
              modelMap[model].output_tokens += out;
            }
          }
          models = Object.keys(modelMap).filter(m => m && m !== 'unknown' && m !== 'null');
          modelBreakdown = models.map(m => ({
            model: m,
            calls: modelMap[m].calls,
            input_tokens: modelMap[m].input_tokens,
            output_tokens: modelMap[m].output_tokens,
            pct: totalCalls > 0 ? Math.round(modelMap[m].calls / totalCalls * 100) : 0
          }));
          dataSource = 'openai_admin_api';
        }
      } catch (e) {
        // Fall through to seals
      }
    }

    // ════════════════════════════════════════════
    // ANTHROPIC: Admin key → pull real data
    // ════════════════════════════════════════════
    if (anthropicKey.startsWith('sk-ant-admin') && dataSource === 'seals_table') {
      try {
        const headers = {
          'x-api-key': anthropicKey,
          'anthropic-version': '2023-06-01',
          'Content-Type': 'application/json'
        };

        // Cost report
        const costResp = await fetch(
          `https://api.anthropic.com/v1/organizations/cost_report?starting_at=${startISO}&ending_at=${endISO}`,
          { headers }
        );
        if (costResp.ok) {
          const costData = await costResp.json();
          // Sum costs from response — adjust based on actual response format
          for (const item of (costData.data || [])) {
            totalCost += parseFloat(item.cost || item.amount || 0);
          }
        }

        // Usage report
        const usageResp = await fetch(
          `https://api.anthropic.com/v1/organizations/usage_report/messages?starting_at=${startISO}&ending_at=${endISO}&bucket_width=1d`,
          { headers }
        );
        if (usageResp.ok) {
          const usageData = await usageResp.json();
          const modelMap = {};
          for (const bucket of (usageData.data || [])) {
            for (const r of (bucket.results || [])) {
              const model = r.model || 'unknown';
              const reqs = r.num_requests || r.request_count || 0;
              const inp = r.input_tokens || 0;
              const out = r.output_tokens || 0;
              totalCalls += reqs;
              totalInputTokens += inp;
              totalOutputTokens += out;
              if (!modelMap[model]) modelMap[model] = { calls: 0, input_tokens: 0, output_tokens: 0 };
              modelMap[model].calls += reqs;
              modelMap[model].input_tokens += inp;
              modelMap[model].output_tokens += out;
            }
          }
          const anthModels = Object.keys(modelMap).filter(m => m && m !== 'unknown');
          models = [...models, ...anthModels];
          modelBreakdown = [...modelBreakdown, ...anthModels.map(m => ({
            model: m,
            calls: modelMap[m].calls,
            input_tokens: modelMap[m].input_tokens,
            output_tokens: modelMap[m].output_tokens,
            pct: totalCalls > 0 ? Math.round(modelMap[m].calls / totalCalls * 100) : 0
          }))];
          dataSource = 'anthropic_admin_api';
        }
      } catch (e) {
        // Fall through to seals
      }
    }

    // ════════════════════════════════════════════
    // FALLBACK: Seals table (for regular keys or if admin APIs fail)
    // ════════════════════════════════════════════
    if (dataSource === 'seals_table') {
      const sealRows = await supabaseSelect(env, 'seals', '*', 'order=timestamp.desc&limit=1000');

      const junkModels = ['n/a', 'unknown', 'test', '', null, undefined];
      const records = (sealRows || []).filter(s => {
        if (junkModels.includes(s.model)) return false;
        if ((s.cost_usd || 0) > 1000) return false;
        return true;
      });
      totalCost = records.reduce((sum, s) => sum + (s.cost_usd || 0), 0);
      totalCalls = records.length;
      models = [...new Set(records.map(s => s.model).filter(Boolean))];
      modelBreakdown = models.map(m => {
        const ms = records.filter(s => s.model === m);
        return {
          model: m,
          cost: ms.reduce((sum, s) => sum + (s.cost_usd || 0), 0),
          calls: ms.length,
          pct: totalCalls > 0 ? Math.round(ms.length / totalCalls * 100) : 0
        };
      });
    }

    // ════════════════════════════════════════════
    // SEAL COVERAGE: How many calls are sealed vs unsealed
    // ════════════════════════════════════════════
    let sealedCount = 0;
    try {
      const sealCountRows = await supabaseSelect(env, 'seals', 'seal_id', 'model=not.in.("n/a","unknown","test")');
      sealedCount = (sealCountRows || []).length;
    } catch (e) {}

    return jsonResponse({
      total_cost: Math.round(totalCost * 10000) / 10000,
      actual_total: Math.round(totalCost * 10000) / 10000,
      total_calls: totalCalls,
      record_count: totalCalls,
      models_analyzed: models,
      model_breakdown: modelBreakdown,
      total_input_tokens: totalInputTokens,
      total_output_tokens: totalOutputTokens,
      sealed_calls: sealedCount,
      unsealed_calls: Math.max(0, totalCalls - sealedCount),
      seal_coverage_pct: totalCalls > 0 ? Math.round(sealedCount / totalCalls * 100) : 0,
      has_data: totalCalls > 0,
      scan_id: requestId,
      data_source: dataSource,
      organization: orgName,
      project: projectName
    });
  } catch (error) {
    console.error('[TimeMachine] Analyze error:', error);
    return jsonResponse({ error: error.message }, 500);
  }
}

/**
 * POST /v1/dark-debt/scan — Dark Debt Scanner
 * Compares provider-reported total calls vs sealed calls to find untracked AI usage.
 * Accepts { openai_key, anthropic_key } — reuses the analyze handler's provider API logic.
 */
async function handleDarkDebtScan(request, env) {
  try {
    const body = await safeParseJSON(request);
    const openaiKey = body?.openai_key || '';
    const anthropicKey = body?.anthropic_key || '';
    const startTime = Math.floor(Date.now() / 1000) - (30 * 86400);
    const startISO = new Date(startTime * 1000).toISOString();
    const endISO = new Date().toISOString();

    let providerTotalCalls = 0;
    let providerTotalCost = 0;
    let providerSource = null;

    // ═══════ Pull provider-reported totals (same logic as analyze) ═══════
    if (openaiKey.startsWith('sk-admin-')) {
      try {
        const headers = { 'Authorization': `Bearer ${openaiKey}`, 'Content-Type': 'application/json' };
        const usageResp = await fetch(
          `https://api.openai.com/v1/organization/usage/completions?start_time=${startTime}&limit=30&bucket_width=1d&group_by[]=model`,
          { headers }
        );
        if (usageResp.ok) {
          const usageData = await usageResp.json();
          for (const bucket of (usageData.data || [])) {
            for (const r of (bucket.results || [])) {
              providerTotalCalls += r.num_model_requests || 0;
            }
          }
        }
        const costsResp = await fetch(
          `https://api.openai.com/v1/organization/costs?start_time=${startTime}&limit=30&bucket_width=1d`,
          { headers }
        );
        if (costsResp.ok) {
          const costsData = await costsResp.json();
          for (const bucket of (costsData.data || [])) {
            for (const r of (bucket.results || [])) {
              const val = parseFloat(r.amount?.value || '0');
              if (!isNaN(val)) providerTotalCost += val;
            }
          }
        }
        providerSource = 'openai_admin_api';
      } catch (e) { /* fall through */ }
    }

    if (anthropicKey.startsWith('sk-ant-admin') && !providerSource) {
      try {
        const headers = { 'x-api-key': anthropicKey, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' };
        const usageResp = await fetch(
          `https://api.anthropic.com/v1/organizations/usage_report/messages?starting_at=${startISO}&ending_at=${endISO}&bucket_width=1d`,
          { headers }
        );
        if (usageResp.ok) {
          const usageData = await usageResp.json();
          for (const bucket of (usageData.data || [])) {
            for (const r of (bucket.results || [])) {
              providerTotalCalls += r.num_requests || r.request_count || 0;
            }
          }
        }
        const costResp = await fetch(
          `https://api.anthropic.com/v1/organizations/cost_report?starting_at=${startISO}&ending_at=${endISO}`,
          { headers }
        );
        if (costResp.ok) {
          const costData = await costResp.json();
          for (const item of (costData.data || [])) {
            providerTotalCost += parseFloat(item.cost || item.amount || 0);
          }
        }
        providerSource = 'anthropic_admin_api';
      } catch (e) { /* fall through */ }
    }

    if (!providerSource) {
      return jsonResponse({
        error: 'Admin key required for Dark Debt scan. Provide an sk-admin-* (OpenAI) or sk-ant-admin* (Anthropic) key.',
        dark_debt_calls: 0,
        dark_debt_pct: 0
      }, 400);
    }

    // ═══════ Count sealed calls from Supabase ═══════
    let sealedTotal = 0;
    let sealedCost = 0;
    try {
      const sealRows = await supabaseSelect(env, 'seals',
        'seal_id,cost_usd',
        `timestamp=gte.${startISO}&model=not.in.("n/a","unknown","test")&limit=10000`
      );
      if (Array.isArray(sealRows)) {
        sealedTotal = sealRows.length;
        sealedCost = sealRows.reduce((sum, s) => sum + (parseFloat(s.cost_usd) || 0), 0);
      }
    } catch (e) { /* sealed count stays 0 */ }

    // ═══════ Compute Dark Debt ═══════
    const darkDebtCalls = Math.max(0, providerTotalCalls - sealedTotal);
    const darkDebtPct = providerTotalCalls > 0 ? Math.round(darkDebtCalls / providerTotalCalls * 1000) / 10 : 0;
    const darkDebtEstimatedCost = providerTotalCalls > 0
      ? Math.round((providerTotalCost * (darkDebtCalls / providerTotalCalls)) * 100) / 100
      : 0;

    return jsonResponse({
      provider_total_calls: providerTotalCalls,
      provider_total_cost: Math.round(providerTotalCost * 10000) / 10000,
      sealed_total: sealedTotal,
      sealed_cost: Math.round(sealedCost * 10000) / 10000,
      dark_debt_calls: darkDebtCalls,
      dark_debt_pct: darkDebtPct,
      dark_debt_estimated_cost: darkDebtEstimatedCost,
      seal_coverage_pct: providerTotalCalls > 0 ? Math.round(sealedTotal / providerTotalCalls * 1000) / 10 : 0,
      provider_source: providerSource,
      period_days: 30,
      scan_id: crypto.randomUUID(),
      severity: darkDebtPct > 50 ? 'critical' : darkDebtPct > 25 ? 'high' : darkDebtPct > 10 ? 'medium' : 'low',
      message: darkDebtPct > 50
        ? `${darkDebtPct}% of your AI calls are unsealed Dark Debt — invisible to your financial controls.`
        : darkDebtPct > 10
        ? `${darkDebtPct}% of AI calls are untracked. Route all traffic through Finault to close the gap.`
        : `Strong seal coverage at ${(100 - darkDebtPct).toFixed(1)}%. ${darkDebtCalls} calls remain unsealed.`
    });
  } catch (error) {
    console.error('[DarkDebt] Scan error:', error);
    return jsonResponse({ error: error.message }, 500);
  }
}

/**
 * POST /v1/audit/invoice — AI Invoice Auditor
 * Compares provider-reported token counts against independent estimates.
 * For MVP: uses chars/4 approximation. Production: use js-tiktoken.
 */
async function handleInvoiceAudit(request, env) {
  try {
    const body = await safeParseJSON(request);
    const startDate = new Date(Date.now() - 30 * 86400 * 1000).toISOString();

    // Fetch sealed calls with token data
    const sealRows = await supabaseSelect(env, 'seals',
      'seal_id,model,provider,cost_usd,tokens_used,timestamp,outcome,custom',
      `timestamp=gte.${startDate}&model=not.in.("n/a","unknown","test")&order=timestamp.desc&limit=5000`
    );

    if (!Array.isArray(sealRows) || sealRows.length === 0) {
      return jsonResponse({
        success: true,
        message: 'No sealed calls found for audit. Route API calls through Finault Gateway first.',
        total_provider_reported: 0,
        total_finault_counted: 0,
        discrepancy_tokens: 0,
        discrepancy_pct: 0,
        discrepancy_cost_usd: 0,
        seals_audited: 0
      });
    }

    let totalProviderReported = 0;
    let totalFinaultCounted = 0;
    let totalProviderCost = 0;
    const modelDiscrepancies = {};
    let sealsWithTokenData = 0;

    for (const seal of sealRows) {
      const providerTokens = seal.tokens_used || 0;
      if (providerTokens <= 0) continue;
      sealsWithTokenData++;

      // Independent token estimate from outcome/custom data
      // For MVP: use provider-reported as baseline and flag statistical outliers
      let finaultEstimate = providerTokens;

      // If we have outcome text data, do independent count (chars/4 approximation)
      const outcomeData = typeof seal.outcome === 'string' ? seal.outcome : JSON.stringify(seal.outcome || '');
      const customData = typeof seal.custom === 'string' ? seal.custom : JSON.stringify(seal.custom || '');

      if (outcomeData.length > 10) {
        // Approximate token count: ~4 chars per token (conservative for English)
        const estimatedOutputTokens = Math.ceil(outcomeData.length / 4);
        // If the estimate differs significantly from provider count, flag it
        if (providerTokens > 0) {
          const ratio = estimatedOutputTokens / providerTokens;
          // Only override if we have enough signal (>100 chars of output)
          if (outcomeData.length > 100 && (ratio < 0.5 || ratio > 2.0)) {
            finaultEstimate = estimatedOutputTokens;
          }
        }
      }

      totalProviderReported += providerTokens;
      totalFinaultCounted += finaultEstimate;
      totalProviderCost += parseFloat(seal.cost_usd) || 0;

      const model = seal.model || 'unknown';
      if (!modelDiscrepancies[model]) {
        modelDiscrepancies[model] = { provider_tokens: 0, finault_tokens: 0, seals: 0, cost: 0 };
      }
      modelDiscrepancies[model].provider_tokens += providerTokens;
      modelDiscrepancies[model].finault_tokens += finaultEstimate;
      modelDiscrepancies[model].seals += 1;
      modelDiscrepancies[model].cost += parseFloat(seal.cost_usd) || 0;
    }

    const discrepancyTokens = Math.abs(totalProviderReported - totalFinaultCounted);
    const discrepancyPct = totalProviderReported > 0 ? Math.round(discrepancyTokens / totalProviderReported * 10000) / 100 : 0;
    const discrepancyCost = totalProviderCost > 0 && totalProviderReported > 0
      ? Math.round(totalProviderCost * (discrepancyTokens / totalProviderReported) * 100) / 100
      : 0;

    const breakdown = Object.entries(modelDiscrepancies).map(([model, data]) => ({
      model,
      provider_tokens: data.provider_tokens,
      finault_tokens: data.finault_tokens,
      discrepancy: Math.abs(data.provider_tokens - data.finault_tokens),
      discrepancy_pct: data.provider_tokens > 0 ? Math.round(Math.abs(data.provider_tokens - data.finault_tokens) / data.provider_tokens * 10000) / 100 : 0,
      seals: data.seals,
      cost: Math.round(data.cost * 100) / 100
    })).sort((a, b) => b.discrepancy - a.discrepancy);

    return jsonResponse({
      success: true,
      total_provider_reported: totalProviderReported,
      total_finault_counted: totalFinaultCounted,
      discrepancy_tokens: discrepancyTokens,
      discrepancy_pct: discrepancyPct,
      discrepancy_cost_usd: discrepancyCost,
      total_provider_cost: Math.round(totalProviderCost * 100) / 100,
      seals_audited: sealsWithTokenData,
      total_seals: sealRows.length,
      model_breakdown: breakdown,
      audit_method: 'approximation_v1',
      audit_note: 'Token counts use chars/4 approximation. Upgrade to tiktoken for exact counts.',
      period_days: 30,
      scan_id: crypto.randomUUID()
    });
  } catch (error) {
    console.error('[InvoiceAudit] Error:', error);
    return jsonResponse({ error: error.message }, 500);
  }
}

/**
 * Time Machine analysis engine (inline for Cloudflare Workers).
 * Mirrors the full 5-engine pipeline from platform/time-machine-engine.js.
 */
function tmRunAnalysis(usageRecords, customerData, attributionMappings, options = {}) {
  const actualTotal = usageRecords.reduce((s, r) => s + parseFloat(r.cost_usd || 0), 0);
  const dates = usageRecords.map(r => r.date).filter(Boolean).sort();
  const models = [...new Set(usageRecords.map(r => r.model).filter(Boolean))].sort();
  const providers = [...new Set(usageRecords.map(r => r.provider).filter(Boolean))].sort();

  // Savings estimation using heuristic categories
  const savingsPct = Math.min(35, Math.max(15,
    (models.length > 3 ? 25 : 18) + (providers.length > 1 ? 5 : 0)
  ));
  const totalSavings = actualTotal * (savingsPct / 100);

  // Build alternate timeline
  const dailyCosts = {};
  for (const r of usageRecords) {
    if (!r.date) continue;
    dailyCosts[r.date] = (dailyCosts[r.date] || 0) + parseFloat(r.cost_usd || 0);
  }
  let cumA = 0, cumO = 0;
  const timeline = Object.entries(dailyCosts).sort().map(([date, cost]) => {
    const opt = cost * (1 - savingsPct / 100);
    cumA += cost; cumO += opt;
    return { date, actual_spend: Math.round(cost * 100) / 100, optimized_spend: Math.round(opt * 100) / 100, cumulative_actual: Math.round(cumA * 100) / 100, cumulative_optimized: Math.round(cumO * 100) / 100 };
  });

  // Customer impact
  const customerImpact = [];
  if (Object.keys(customerData).length > 0) {
    const totalRev = Object.values(customerData).reduce((s, c) => s + (c.total_paid || 0), 0);
    const savingsRatio = actualTotal > 0 ? totalSavings / actualTotal : 0;

    for (const [custId, cust] of Object.entries(customerData)) {
      const mapping = attributionMappings.find(m => m.stripe_customer_id === custId);
      let ac = 0;
      if (mapping?.strategy === 'project') {
        ac = usageRecords.filter(r => r.project_id === mapping.match_value).reduce((s, r) => s + parseFloat(r.cost_usd || 0), 0);
      } else if (mapping?.strategy === 'api_key') {
        ac = usageRecords.filter(r => r.api_key_id === mapping.match_value).reduce((s, r) => s + parseFloat(r.cost_usd || 0), 0);
      } else {
        const share = totalRev > 0 ? (cust.total_paid || 0) / totalRev : 0;
        ac = actualTotal * share;
      }
      const oc = ac * (1 - savingsRatio);
      const rev = cust.total_paid || 0;
      const am = rev > 0 ? ((rev - ac) / rev) * 100 : 0;
      const om = rev > 0 ? ((rev - oc) / rev) * 100 : 0;
      customerImpact.push({
        customer_id: custId, name: cust.name || custId, revenue: Math.round(rev * 100) / 100,
        actual_cost: Math.round(ac * 100) / 100, optimized_cost: Math.round(oc * 100) / 100,
        actual_margin_percent: Math.round(am * 10) / 10, optimized_margin_percent: Math.round(om * 10) / 10,
        margin_improvement: Math.round((om - am) * 10) / 10, is_underwater: ac > rev && rev > 0,
      });
    }
    customerImpact.sort((a, b) => a.actual_margin_percent - b.actual_margin_percent);
  }

  // Finault Score
  const ce = Math.max(0, Math.min(100, 100 - savingsPct * 2));
  let mh = 70;
  if (customerImpact.length > 0) {
    const avgM = customerImpact.reduce((s, c) => s + c.actual_margin_percent, 0) / customerImpact.length;
    mh = Math.max(0, Math.min(100, avgM + 20));
  }
  let ts = 50;
  if (timeline.length >= 60) {
    const half = Math.floor(timeline.length / 2);
    const fA = timeline.slice(0, half).reduce((s, d) => s + d.actual_spend, 0) / half;
    const sA = timeline.slice(half).reduce((s, d) => s + d.actual_spend, 0) / (timeline.length - half);
    if (fA > 0) ts = Math.max(0, Math.min(100, 50 - ((sA - fA) / fA) * 100));
  }
  const mo = Math.max(0, Math.min(100, 100 - savingsPct * 1.5));
  let gov = 30;
  if (customerImpact.length > 0) gov += 35;
  if (timeline.length > 90) gov += 20;
  if (providers.length > 1) gov += 15;
  const div = Math.min(100, providers.length * 33);
  const overall = Math.round(ce * 0.25 + mh * 0.25 + ts * 0.15 + mo * 0.15 + gov * 0.10 + div * 0.10);

  return {
    actual_total: Math.round(actualTotal * 100) / 100,
    optimized_total: Math.round((actualTotal - totalSavings) * 100) / 100,
    recoverable_spend: Math.round(totalSavings * 100) / 100,
    savings_percent: Math.round(savingsPct * 10) / 10,
    savings_by_category: {
      model_substitution: Math.round(totalSavings * 0.40 * 100) / 100,
      batch_eligibility: Math.round(totalSavings * 0.20 * 100) / 100,
      cache_opportunity: Math.round(totalSavings * 0.15 * 100) / 100,
      price_migration: Math.round(totalSavings * 0.15 * 100) / 100,
      cross_provider: Math.round(totalSavings * 0.10 * 100) / 100,
    },
    alternate_timeline: timeline,
    customer_impact: customerImpact,
    finault_score: {
      overall: Math.max(0, Math.min(100, overall)),
      dimensions: { cost_efficiency: Math.round(ce), margin_health: Math.round(mh), trend_trajectory: Math.round(ts), model_optimization: Math.round(mo), governance_maturity: Math.round(gov), diversification: Math.round(div) },
    },
    analysis_period: { start: dates[0] || null, end: dates[dates.length - 1] || null },
    models_analyzed: models, providers_analyzed: providers,
    record_count: usageRecords.length, generated_at: new Date().toISOString(),
  };
}

/**
 * GET /v1/time-machine/analyses — List past analyses
 */
async function handleListAnalyses(request, env) {
  try {
    const orgId = request._user?.orgId || 'bc3341ee-6061-408f-b13c-547c8b297e52';

    const data = await supabaseSelect(env, 'time_machine_analyses',
      'id,analysis_period_start,analysis_period_end,actual_total_usd,optimized_total_usd,recoverable_usd,savings_percent,models_analyzed,providers_analyzed,created_at',
      `org_id=eq.${orgId}&order=created_at.desc&limit=50`);

    return jsonResponse({ analyses: data || [], total: (data || []).length });
  } catch (error) {
    return jsonResponse({ error: error.message }, 500);
  }
}

/**
 * GET /v1/time-machine/analyses/:id — Get specific analysis (public-readable for shareable links)
 */
async function handleGetAnalysis(request, env, analysisId) {
  try {
    const data = await supabaseSelect(env, 'time_machine_analyses', '*', `id=eq.${analysisId}`);
    if (!data || data.length === 0) return jsonResponse({ error: 'Analysis not found' }, 404);
    return jsonResponse(data[0]);
  } catch (error) {
    return jsonResponse({ error: error.message }, 500);
  }
}

/**
 * GET /v1/time-machine/attribution — Get attribution mappings
 */
async function handleGetAttribution(request, env) {
  try {
    const orgId = request._user?.orgId;
    if (!orgId) return jsonResponse({ error: 'Unauthorized' }, 401);
    const data = await supabaseSelect(env, 'customer_attribution_mappings', '*', `org_id=eq.${orgId}&order=created_at.asc`);
    return jsonResponse({ mappings: data || [] });
  } catch (error) {
    return jsonResponse({ error: error.message }, 500);
  }
}

/**
 * POST /v1/time-machine/attribution — Save attribution mappings
 */
async function handleSaveAttribution(request, env) {
  try {
    const orgId = request._user?.orgId;
    if (!orgId) return jsonResponse({ error: 'Unauthorized' }, 401);
    const body = await request.json();
    const { mappings = [] } = body;

    if (!Array.isArray(mappings) || mappings.length === 0) {
      return jsonResponse({ error: 'mappings array required' }, 400);
    }

    let saved = 0;
    const errors = [];
    for (const m of mappings) {
      if (!m.stripe_customer_id) { errors.push({ error: 'Missing stripe_customer_id' }); continue; }
      try {
        await supabaseUpsert(env, 'customer_attribution_mappings', [{
          org_id: orgId, stripe_customer_id: m.stripe_customer_id,
          customer_name: m.customer_name || null, strategy: m.strategy || 'proportional',
          match_value: m.match_value || null, weight: m.weight || 1.0,
          updated_at: new Date().toISOString(),
        }], 'org_id,stripe_customer_id,match_value', false);
        saved++;
      } catch (e) {
        errors.push({ customer: m.stripe_customer_id, error: e.message });
      }
    }
    return jsonResponse({ saved, errors, total: mappings.length });
  } catch (error) {
    return jsonResponse({ error: error.message }, 500);
  }
}

/**
 * POST /v1/time-machine/attribution/suggest — Auto-suggest attribution mappings
 */
async function handleSuggestAttribution(request, env) {
  try {
    const orgId = request._user?.orgId;
    if (!orgId) return jsonResponse({ error: 'Unauthorized' }, 401);

    const usage = await supabaseSelect(env, 'historical_usage', 'project_id,api_key_id,cost_usd', `org_id=eq.${orgId}`);
    const revenue = await supabaseSelect(env, 'stripe_revenue_history', 'stripe_customer_id,customer_name,customer_email,revenue_usd', `org_id=eq.${orgId}`);

    const customerData = {};
    for (const row of revenue || []) {
      if (!customerData[row.stripe_customer_id]) customerData[row.stripe_customer_id] = { name: row.customer_name, email: row.customer_email, total_paid: 0 };
      customerData[row.stripe_customer_id].total_paid += parseFloat(row.revenue_usd || 0);
    }

    if (!usage?.length || Object.keys(customerData).length === 0) {
      return jsonResponse({ suggestions: [], message: 'Need both usage and Stripe data for suggestions.' });
    }

    // Name matching heuristic
    const customers = Object.entries(customerData).map(([id, d]) => ({ id, name: (d.name || '').toLowerCase().trim(), revenue: d.total_paid || 0 }));
    const projectCosts = {};
    for (const r of usage) { const p = r.project_id || 'default'; projectCosts[p] = (projectCosts[p] || 0) + parseFloat(r.cost_usd || 0); }
    const projects = Object.entries(projectCosts).map(([id, cost]) => ({ id, cost })).sort((a, b) => b.cost - a.cost);

    const suggestions = [];
    const matched = new Set();
    const pMatched = new Set();

    for (const cust of customers) {
      if (!cust.name) continue;
      const tokens = cust.name.replace(/[^a-z0-9\s]/g, '').split(/\s+/).filter(t => t.length > 2);
      for (const proj of projects) {
        if (pMatched.has(proj.id)) continue;
        if (tokens.some(t => proj.id.toLowerCase().includes(t))) {
          suggestions.push({ stripe_customer_id: cust.id, customer_name: customerData[cust.id].name, strategy: 'project', match_value: proj.id, confidence: 0.75, reason: `Project matches customer name` });
          matched.add(cust.id); pMatched.add(proj.id); break;
        }
      }
    }

    const totalRev = customers.reduce((s, c) => s + c.revenue, 0);
    for (const cust of customers) {
      if (matched.has(cust.id)) continue;
      suggestions.push({ stripe_customer_id: cust.id, customer_name: customerData[cust.id].name, strategy: 'proportional', match_value: null, weight: totalRev > 0 ? Math.round((cust.revenue / totalRev) * 10000) / 10000 : 1 / customers.length, confidence: 0.25, reason: 'Proportional by revenue' });
    }

    return jsonResponse({ suggestions: suggestions.sort((a, b) => b.confidence - a.confidence) });
  } catch (error) {
    return jsonResponse({ error: error.message }, 500);
  }
}

/**
 * GET /v1/time-machine/status/:syncId — Check sync progress
 */
async function handleSyncStatus(request, env, syncId) {
  try {
    const data = await supabaseSelect(env, 'raw_sync_payloads', 'payload,fetched_at', `endpoint=eq.sync_progress_${syncId}&order=fetched_at.desc&limit=1`);
    if (data && data.length > 0) {
      const payload = typeof data[0].payload === 'string' ? JSON.parse(data[0].payload) : data[0].payload;
      return jsonResponse(payload);
    }
    // Check if sync exists
    const start = await supabaseSelect(env, 'raw_sync_payloads', 'payload', `endpoint=eq.sync_start&order=fetched_at.desc&limit=5`);
    const found = (start || []).find(s => {
      const p = typeof s.payload === 'string' ? JSON.parse(s.payload) : s.payload;
      return p.sync_id === syncId;
    });
    if (found) return jsonResponse({ sync_id: syncId, status: 'in_progress' });
    return jsonResponse({ error: 'Sync not found' }, 404);
  } catch (error) {
    return jsonResponse({ error: error.message }, 500);
  }
}

// ── Supabase helpers for Time Machine (use native fetch) ──────────────────

async function supabaseSelect(env, table, select, filter) {
  const url = `${env.SUPABASE_URL}/rest/v1/${table}?select=${select}&${filter}`;
  const resp = await fetch(url, {
    headers: { 'apikey': (env.SUPABASE_SERVICE_KEY || env.SUPABASE_KEY) || env.SUPABASE_KEY, 'Authorization': `Bearer ${(env.SUPABASE_SERVICE_KEY || env.SUPABASE_KEY) || env.SUPABASE_KEY}` },
  });
  if (!resp.ok) return [];
  return resp.json();
}

async function supabaseInsert(env, table, rows) {
  const body = Array.isArray(rows) ? rows : [rows];
  const resp = await fetch(`${env.SUPABASE_URL}/rest/v1/${table}`, {
    method: 'POST',
    headers: {
      'apikey': (env.SUPABASE_SERVICE_KEY || env.SUPABASE_KEY) || env.SUPABASE_KEY,
      'Authorization': `Bearer ${(env.SUPABASE_SERVICE_KEY || env.SUPABASE_KEY) || env.SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation',
    },
    body: JSON.stringify(body),
  });
  if (!resp.ok) return null;
  return resp.json();
}

async function supabaseUpsert(env, table, rows, onConflict, ignoreDuplicates = false) {
  const body = Array.isArray(rows) ? rows : [rows];
  const prefer = ignoreDuplicates ? 'return=representation,resolution=ignore-duplicates' : 'return=representation,resolution=merge-duplicates';
  const resp = await fetch(`${env.SUPABASE_URL}/rest/v1/${table}?on_conflict=${onConflict}`, {
    method: 'POST',
    headers: {
      'apikey': (env.SUPABASE_SERVICE_KEY || env.SUPABASE_KEY) || env.SUPABASE_KEY,
      'Authorization': `Bearer ${(env.SUPABASE_SERVICE_KEY || env.SUPABASE_KEY) || env.SUPABASE_KEY}`,
      'Content-Type': 'application/json',
      'Prefer': prefer,
    },
    body: JSON.stringify(body),
  });
  if (!resp.ok) throw new Error(`Upsert failed: ${resp.status}`);
  return resp.json();
}

// ============================================================================
// ============ MARGIN ROUTING (B3) ============
// ============================================================================

const MODEL_COST_TIERS = {
  'gpt-4o': { tier: 'premium', fallback: 'gpt-4o-mini' },
  'gpt-4-turbo': { tier: 'premium', fallback: 'gpt-4o-mini' },
  'gpt-4': { tier: 'premium', fallback: 'gpt-4o-mini' },
  'gpt-4o-mini': { tier: 'economy', fallback: 'gpt-4o-mini' },
  'gpt-3.5-turbo': { tier: 'economy', fallback: 'gpt-3.5-turbo' },
  'claude-3-opus': { tier: 'premium', fallback: 'claude-3-haiku' },
  'claude-3-sonnet': { tier: 'standard', fallback: 'claude-3-haiku' },
  'claude-3-haiku': { tier: 'economy', fallback: 'claude-3-haiku' },
  'claude-3.5-sonnet': { tier: 'premium', fallback: 'claude-3-haiku' },
};

const marginCache = new Map();

function getCacheKey(orgId, costCenter) {
  return `margin:${orgId}:${costCenter}`;
}

function isCacheValid(cached, ttl) {
  if (!cached) return false;
  const ageSeconds = (Date.now() - cached.timestamp) / 1000;
  return ageSeconds < ttl;
}

async function getCustomerMargin(orgId, costCenter, env, ttl = 300) {
  const cacheKey = getCacheKey(orgId, costCenter);
  const cached = marginCache.get(cacheKey);

  if (cached && isCacheValid(cached, ttl)) {
    return cached.data;
  }

  try {
    const usageResponse = await fetch(
      `${env.SUPABASE_URL}/rest/v1/usage?organization_id=eq.${orgId}&cost_center=eq.${encodeURIComponent(costCenter)}&created_at=gte.now()-30days&select=total_cost:sum(cost),request_count:count()`,
      { headers: getSupabaseHeaders(env) }
    );

    const usageData = await usageResponse.json();
    const totalCost = usageData[0]?.total_cost || 0;
    const requestCount = usageData[0]?.request_count || 0;

    const revenueResponse = await fetch(
      `${env.SUPABASE_URL}/rest/v1/revenue_entries?org_id=eq.${orgId}&cost_center=eq.${encodeURIComponent(costCenter)}&select=total_revenue:sum(revenue_amount)`,
      { headers: getSupabaseHeaders(env) }
    );

    const revenueData = await revenueResponse.json();
    const totalRevenue = revenueData[0]?.total_revenue || 0;

    let marginPct = 0;
    if (totalRevenue > 0) {
      marginPct = ((totalRevenue - totalCost) / totalRevenue) * 100;
    } else if (totalCost > 0) {
      marginPct = -100;
    }

    const result = {
      margin_pct: parseFloat(marginPct.toFixed(2)),
      total_cost: parseFloat(totalCost.toFixed(2)),
      total_revenue: parseFloat(totalRevenue.toFixed(2)),
      request_count: requestCount,
    };

    marginCache.set(cacheKey, { data: result, timestamp: Date.now() });
    return result;
  } catch (error) {
    console.error(`Error fetching margin for ${orgId}/${costCenter}:`, error);
    return { margin_pct: 50, total_cost: 0, total_revenue: 0, request_count: 0 };
  }
}

async function logRoutingDecision(orgId, costCenter, originalModel, routedModel, margin, ruleTriggered, actionTaken, env) {
  try {
    await fetch(`${env.SUPABASE_URL}/rest/v1/margin_routing_log`, {
      method: 'POST',
      headers: getSupabaseHeaders(env),
      body: JSON.stringify({
        org_id: orgId,
        cost_center: costCenter,
        original_model: originalModel,
        routed_model: routedModel,
        customer_margin_pct: parseFloat(margin.toFixed(2)),
        rule_triggered: ruleTriggered,
        action_taken: actionTaken,
      }),
    });
  } catch (error) {
    console.error('Error logging routing decision:', error);
  }
}

function evaluateRoutingRules(rules, margin) {
  const sortedRules = [...rules].sort((a, b) => a.threshold - b.threshold);
  for (const rule of sortedRules) {
    if (margin <= rule.threshold) {
      return rule;
    }
  }
  return null;
}

async function handleGetMarginRouting(request, env) {
  const orgId = getOrgIdFromAuth(request);
  if (!orgId) {
    return errorResponse('AUTH_REQUIRED', 'Authorization required', 401);
  }

  try {
    const response = await fetch(
      `${env.SUPABASE_URL}/rest/v1/margin_routing_rules?org_id=eq.${orgId}&select=*`,
      { headers: getSupabaseHeaders(env) }
    );

    const data = await response.json();

    if (data.length === 0) {
      return jsonResponse({
        enabled: false,
        rules: [],
        fallback_model: 'gpt-4o-mini',
        margin_cache_ttl_seconds: 300,
      });
    }

    const config = data[0];
    return jsonResponse({
      id: config.id,
      enabled: config.enabled,
      rules: config.rules || [],
      fallback_model: config.fallback_model,
      margin_cache_ttl_seconds: config.margin_cache_ttl_seconds,
      created_at: config.created_at,
      updated_at: config.updated_at,
    });
  } catch (error) {
    console.error('Error fetching margin routing config:', error);
    return errorResponse('INTERNAL_ERROR', 'Failed to fetch configuration', 500);
  }
}

async function handleUpdateMarginRouting(request, env) {
  const orgId = getOrgIdFromAuth(request);
  if (!orgId) {
    return errorResponse('AUTH_REQUIRED', 'Authorization required', 401);
  }

  try {
    const body = await request.json();

    if (body.rules && Array.isArray(body.rules)) {
      for (const rule of body.rules) {
        if (!rule.name || typeof rule.threshold !== 'number' || !rule.action) {
          return errorResponse(
            'INVALID_RULE',
            'Each rule must have: name (string), threshold (number), action (string)',
            400
          );
        }
      }
    }

    if (body.fallback_model && !MODEL_COST_TIERS[body.fallback_model]) {
      return errorResponse(
        'INVALID_MODEL',
        `Fallback model '${body.fallback_model}' is not supported`,
        400
      );
    }

    const existingResponse = await fetch(
      `${env.SUPABASE_URL}/rest/v1/margin_routing_rules?org_id=eq.${orgId}&select=id`,
      { headers: getSupabaseHeaders(env) }
    );

    const existing = await existingResponse.json();

    if (existing.length > 0) {
      const updateResponse = await fetch(
        `${env.SUPABASE_URL}/rest/v1/margin_routing_rules?org_id=eq.${orgId}`,
        {
          method: 'PATCH',
          headers: getSupabaseHeaders(env),
          body: JSON.stringify({
            enabled: body.enabled !== undefined ? body.enabled : undefined,
            rules: body.rules || undefined,
            fallback_model: body.fallback_model || undefined,
            margin_cache_ttl_seconds: body.margin_cache_ttl_seconds || undefined,
            updated_at: new Date().toISOString(),
          }),
        }
      );

      if (!updateResponse.ok) {
        throw new Error('Failed to update configuration');
      }

      const updated = await updateResponse.json();
      return jsonResponse(updated[0], 200);
    } else {
      const insertResponse = await fetch(
        `${env.SUPABASE_URL}/rest/v1/margin_routing_rules`,
        {
          method: 'POST',
          headers: getSupabaseHeaders(env),
          body: JSON.stringify({
            org_id: orgId,
            enabled: body.enabled || false,
            rules: body.rules || [],
            fallback_model: body.fallback_model || 'gpt-4o-mini',
            margin_cache_ttl_seconds: body.margin_cache_ttl_seconds || 300,
          }),
        }
      );

      if (!insertResponse.ok) {
        throw new Error('Failed to create configuration');
      }

      const created = await insertResponse.json();
      return jsonResponse(created[0], 201);
    }
  } catch (error) {
    console.error('Error updating margin routing config:', error);
    return errorResponse('INTERNAL_ERROR', 'Failed to update configuration', 500);
  }
}

async function handleGetRoutingLog(request, env) {
  const orgId = getOrgIdFromAuth(request);
  if (!orgId) {
    return errorResponse('AUTH_REQUIRED', 'Authorization required', 401);
  }

  try {
    const url = new URL(request.url);
    const costCenter = url.searchParams.get('cost_center');
    const limit = parseInt(url.searchParams.get('limit') || '50', 10);

    let query = `org_id=eq.${orgId}`;
    if (costCenter) {
      query += `&cost_center=eq.${encodeURIComponent(costCenter)}`;
    }
    query += `&order=created_at.desc&limit=${limit}`;

    const response = await fetch(
      `${env.SUPABASE_URL}/rest/v1/margin_routing_log?${query}&select=*`,
      { headers: getSupabaseHeaders(env) }
    );

    const data = await response.json();

    return jsonResponse({
      entries: data,
      count: data.length,
      limit,
    });
  } catch (error) {
    console.error('Error fetching routing log:', error);
    return errorResponse('INTERNAL_ERROR', 'Failed to fetch routing log', 500);
  }
}

// ============================================================================
// ============ CUSTOMER BUDGETS (B4) ============
// ============================================================================

const getCurrentPeriodBudgets = () => {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
};

const getDaysRemainingInMonthBudgets = () => {
  const now = new Date();
  const lastDay = new Date(now.getFullYear(), now.getMonth() + 1, 0);
  return lastDay.getDate() - now.getDate();
};

const calculateUtilization = (currentSpend, monthlyLimit) => {
  if (!monthlyLimit || monthlyLimit <= 0) return 0;
  return Math.round((currentSpend / monthlyLimit) * 100);
};

async function handleListCustomerBudgets(request, env) {
  try {
    const orgId = getOrgIdFromAuth(request);
    const url = new URL(request.url);
    const statusFilter = url.searchParams.get('status');

    const query = new URL(`${env.SUPABASE_URL}/rest/v1/customer_budgets`, env.SUPABASE_URL);
    query.searchParams.set('org_id', `eq.${orgId}`);
    query.searchParams.set('status', `eq.active`);
    query.searchParams.set('select', '*');

    const response = await fetch(query.toString(), {
      headers: getSupabaseHeaders(env)
    });

    if (!response.ok) {
      console.error(`[CUSTOMER_BUDGETS] Supabase query failed: ${response.status}`);
      return errorResponse('DB_ERROR', 'Failed to retrieve customer budgets', response.status);
    }

    const budgets = await response.json();

    const enrichedBudgets = budgets.map(budget => {
      const utilization = calculateUtilization(budget.current_spend, budget.monthly_limit);
      const status = utilization >= 100 ? 'exceeded' : utilization >= 75 ? 'warning' : 'active';

      return {
        cost_center: budget.cost_center,
        budget_type: budget.budget_type,
        monthly_limit: parseFloat(budget.monthly_limit),
        revenue_pct_cap: budget.revenue_pct_cap ? parseFloat(budget.revenue_pct_cap) : null,
        auto_adjust: budget.auto_adjust,
        current_spend: parseFloat(budget.current_spend),
        remaining: Math.max(0, parseFloat(budget.monthly_limit) - parseFloat(budget.current_spend)),
        utilization_pct: utilization,
        status: status,
        action_on_exceed: budget.action_on_exceed,
        alert_thresholds: budget.alert_thresholds || [75, 90, 100],
        last_refreshed_at: budget.last_refreshed_at,
        created_at: budget.created_at,
        updated_at: budget.updated_at
      };
    });

    const filtered = statusFilter
      ? enrichedBudgets.filter(b => b.status === statusFilter)
      : enrichedBudgets;

    return jsonResponse({
      orgId,
      total: filtered.length,
      budgets: filtered
    });
  } catch (error) {
    console.error(`[CUSTOMER_BUDGETS] List error: ${error.message}`);
    return errorResponse('INTERNAL_ERROR', error.message);
  }
}

async function handleCreateCustomerBudget(request, env) {
  try {
    const orgId = getOrgIdFromAuth(request);
    const body = await request.json();

    if (!body.cost_center || typeof body.cost_center !== 'string') {
      return errorResponse('INVALID_REQUEST', 'Missing or invalid required field: cost_center');
    }

    const budgetType = body.budget_type || 'revenue_pct';
    if (!['fixed', 'revenue_pct'].includes(budgetType)) {
      return errorResponse('INVALID_REQUEST', 'budget_type must be "fixed" or "revenue_pct"');
    }

    const actionOnExceed = body.action_on_exceed || 'alert';
    if (!['alert', 'throttle', 'block'].includes(actionOnExceed)) {
      return errorResponse('INVALID_REQUEST', 'action_on_exceed must be "alert", "throttle", or "block"');
    }

    let monthlyLimit = body.monthly_limit;

    if (budgetType === 'revenue_pct') {
      const revQuery = new URL(`${env.SUPABASE_URL}/rest/v1/revenue_entries`, env.SUPABASE_URL);
      revQuery.searchParams.set('cost_center', `eq.${body.cost_center}`);
      revQuery.searchParams.set('period', `eq.${getCurrentPeriodBudgets()}`);
      revQuery.searchParams.set('select', 'amount');
      revQuery.searchParams.set('limit', '1');

      const revResponse = await fetch(revQuery.toString(), {
        headers: getSupabaseHeaders(env)
      });

      if (revResponse.ok) {
        const revData = await revResponse.json();
        if (revData.length > 0) {
          const revenue = parseFloat(revData[0].amount);
          const revenuePctCap = body.revenue_pct_cap || 80;
          monthlyLimit = (revenue * revenuePctCap) / 100;
        } else {
          monthlyLimit = body.monthly_limit || 1000;
        }
      } else {
        monthlyLimit = body.monthly_limit || 1000;
      }
    } else if (!monthlyLimit || typeof monthlyLimit !== 'number') {
      return errorResponse('INVALID_REQUEST', 'monthly_limit required for fixed budget type');
    }

    const budgetId = crypto.randomUUID();
    const now = new Date().toISOString();
    const currentPeriod = getCurrentPeriodBudgets();

    const newBudget = {
      id: budgetId,
      org_id: orgId,
      cost_center: body.cost_center,
      budget_type: budgetType,
      monthly_limit: monthlyLimit,
      revenue_pct_cap: body.revenue_pct_cap || 80,
      auto_adjust: body.auto_adjust !== false,
      action_on_exceed: actionOnExceed,
      alert_thresholds: body.alert_thresholds || [75, 90, 100],
      status: 'active',
      current_period: currentPeriod,
      current_spend: 0,
      last_refreshed_at: now,
      created_at: now,
      updated_at: now
    };

    const insertResponse = await fetch(
      `${env.SUPABASE_URL}/rest/v1/customer_budgets`,
      {
        method: 'POST',
        headers: getSupabaseHeaders(env),
        body: JSON.stringify(newBudget)
      }
    );

    if (!insertResponse.ok) {
      const errorData = await insertResponse.text();
      console.error(`[CUSTOMER_BUDGETS] Insert failed: ${insertResponse.status} - ${errorData}`);
      return errorResponse('DB_ERROR', 'Failed to create customer budget', insertResponse.status);
    }

    return jsonResponse(newBudget, 201);
  } catch (error) {
    console.error(`[CUSTOMER_BUDGETS] Create error: ${error.message}`);
    return errorResponse('INTERNAL_ERROR', error.message);
  }
}

async function handleUpdateCustomerBudget(request, env, costCenter) {
  try {
    const orgId = getOrgIdFromAuth(request);
    const body = await request.json();

    if (!costCenter || typeof costCenter !== 'string') {
      return errorResponse('INVALID_REQUEST', 'Valid cost_center required in URL');
    }

    const getQuery = new URL(`${env.SUPABASE_URL}/rest/v1/customer_budgets`, env.SUPABASE_URL);
    getQuery.searchParams.set('org_id', `eq.${orgId}`);
    getQuery.searchParams.set('cost_center', `eq.${costCenter}`);
    getQuery.searchParams.set('select', '*');

    const getResponse = await fetch(getQuery.toString(), {
      headers: getSupabaseHeaders(env)
    });

    if (!getResponse.ok) {
      return errorResponse('DB_ERROR', 'Failed to fetch budget', getResponse.status);
    }

    const budgets = await getResponse.json();
    if (budgets.length === 0) {
      return errorResponse('NOT_FOUND', `Budget not found for cost_center: ${costCenter}`, 404);
    }

    const existingBudget = budgets[0];
    const updates = { ...existingBudget };

    if (body.budget_type) {
      if (!['fixed', 'revenue_pct'].includes(body.budget_type)) {
        return errorResponse('INVALID_REQUEST', 'budget_type must be "fixed" or "revenue_pct"');
      }
      updates.budget_type = body.budget_type;
    }

    if (body.monthly_limit !== undefined) {
      updates.monthly_limit = body.monthly_limit;
    }

    if (body.revenue_pct_cap !== undefined) {
      updates.revenue_pct_cap = body.revenue_pct_cap;
    }

    if (body.auto_adjust !== undefined) {
      updates.auto_adjust = body.auto_adjust;
    }

    if (body.action_on_exceed) {
      if (!['alert', 'throttle', 'block'].includes(body.action_on_exceed)) {
        return errorResponse('INVALID_REQUEST', 'action_on_exceed must be "alert", "throttle", or "block"');
      }
      updates.action_on_exceed = body.action_on_exceed;
    }

    if (body.alert_thresholds) {
      updates.alert_thresholds = body.alert_thresholds;
    }

    updates.updated_at = new Date().toISOString();

    const updateResponse = await fetch(
      `${env.SUPABASE_URL}/rest/v1/customer_budgets?org_id=eq.${orgId}&cost_center=eq.${encodeURIComponent(costCenter)}`,
      {
        method: 'PATCH',
        headers: getSupabaseHeaders(env),
        body: JSON.stringify(updates)
      }
    );

    if (!updateResponse.ok) {
      const errorData = await updateResponse.text();
      console.error(`[CUSTOMER_BUDGETS] Update failed: ${updateResponse.status} - ${errorData}`);
      return errorResponse('DB_ERROR', 'Failed to update customer budget', updateResponse.status);
    }

    return jsonResponse(updates);
  } catch (error) {
    console.error(`[CUSTOMER_BUDGETS] Update error: ${error.message}`);
    return errorResponse('INTERNAL_ERROR', error.message);
  }
}

async function handleDeleteCustomerBudget(request, env, costCenter) {
  try {
    const orgId = getOrgIdFromAuth(request);

    if (!costCenter || typeof costCenter !== 'string') {
      return errorResponse('INVALID_REQUEST', 'Valid cost_center required in URL');
    }

    const updateResponse = await fetch(
      `${env.SUPABASE_URL}/rest/v1/customer_budgets?org_id=eq.${orgId}&cost_center=eq.${encodeURIComponent(costCenter)}`,
      {
        method: 'PATCH',
        headers: getSupabaseHeaders(env),
        body: JSON.stringify({
          status: 'inactive',
          updated_at: new Date().toISOString()
        })
      }
    );

    if (!updateResponse.ok) {
      const errorData = await updateResponse.text();
      console.error(`[CUSTOMER_BUDGETS] Delete failed: ${updateResponse.status} - ${errorData}`);
      return errorResponse('DB_ERROR', 'Failed to delete customer budget', updateResponse.status);
    }

    return jsonResponse({
      deleted: true,
      cost_center: costCenter,
      orgId
    });
  } catch (error) {
    console.error(`[CUSTOMER_BUDGETS] Delete error: ${error.message}`);
    return errorResponse('INTERNAL_ERROR', error.message);
  }
}

async function handleCheckCustomerBudget(request, env, costCenter) {
  try {
    const orgId = getOrgIdFromAuth(request);

    if (!costCenter || typeof costCenter !== 'string') {
      return errorResponse('INVALID_REQUEST', 'Valid cost_center required in URL');
    }

    const getQuery = new URL(`${env.SUPABASE_URL}/rest/v1/customer_budgets`, env.SUPABASE_URL);
    getQuery.searchParams.set('org_id', `eq.${orgId}`);
    getQuery.searchParams.set('cost_center', `eq.${costCenter}`);
    getQuery.searchParams.set('status', `eq.active`);
    getQuery.searchParams.set('select', '*');

    const getResponse = await fetch(getQuery.toString(), {
      headers: getSupabaseHeaders(env)
    });

    if (!getResponse.ok) {
      return errorResponse('DB_ERROR', 'Failed to fetch budget status', getResponse.status);
    }

    const budgets = await getResponse.json();
    if (budgets.length === 0) {
      return errorResponse('NOT_FOUND', `Budget not found for cost_center: ${costCenter}`, 404);
    }

    const budget = budgets[0];
    const currentSpend = parseFloat(budget.current_spend);
    const monthlyLimit = parseFloat(budget.monthly_limit);
    const utilization = calculateUtilization(currentSpend, monthlyLimit);
    const daysRemaining = getDaysRemainingInMonthBudgets();
    const dailyBudget = monthlyLimit / 30;
    const projectedMonthEnd = currentSpend + (dailyBudget * daysRemaining);

    return jsonResponse({
      cost_center: budget.cost_center,
      budget_type: budget.budget_type,
      monthly_limit: monthlyLimit,
      current_spend: currentSpend,
      remaining: Math.max(0, monthlyLimit - currentSpend),
      utilization_pct: utilization,
      days_remaining_in_period: daysRemaining,
      projected_end_of_month_spend: Math.round(projectedMonthEnd * 100) / 100,
      will_exceed: projectedMonthEnd > monthlyLimit,
      projected_exceed_date: projectedMonthEnd > monthlyLimit
        ? new Date(new Date().getTime() + (daysRemaining * 24 * 60 * 60 * 1000)).toISOString().split('T')[0]
        : null,
      action_on_exceed: budget.action_on_exceed,
      alert_thresholds: budget.alert_thresholds,
      status: utilization >= 100 ? 'exceeded' : utilization >= 75 ? 'warning' : 'active',
      last_refreshed_at: budget.last_refreshed_at,
      updated_at: budget.updated_at
    });
  } catch (error) {
    console.error(`[CUSTOMER_BUDGETS] Check error: ${error.message}`);
    return errorResponse('INTERNAL_ERROR', error.message);
  }
}

async function handleRefreshRevenueBudgets(request, env) {
  try {
    const orgId = getOrgIdFromAuth(request);
    const currentPeriod = getCurrentPeriodBudgets();

    const getQuery = new URL(`${env.SUPABASE_URL}/rest/v1/customer_budgets`, env.SUPABASE_URL);
    getQuery.searchParams.set('org_id', `eq.${orgId}`);
    getQuery.searchParams.set('budget_type', `eq.revenue_pct`);
    getQuery.searchParams.set('status', `eq.active`);
    getQuery.searchParams.set('select', '*');

    const getResponse = await fetch(getQuery.toString(), {
      headers: getSupabaseHeaders(env)
    });

    if (!getResponse.ok) {
      return errorResponse('DB_ERROR', 'Failed to fetch budgets for refresh', getResponse.status);
    }

    const budgets = await getResponse.json();
    const refreshed = [];
    const failed = [];

    for (const budget of budgets) {
      try {
        const revQuery = new URL(`${env.SUPABASE_URL}/rest/v1/revenue_entries`, env.SUPABASE_URL);
        revQuery.searchParams.set('cost_center', `eq.${budget.cost_center}`);
        revQuery.searchParams.set('period', `eq.${currentPeriod}`);
        revQuery.searchParams.set('select', 'amount');
        revQuery.searchParams.set('limit', '1');

        const revResponse = await fetch(revQuery.toString(), {
          headers: getSupabaseHeaders(env)
        });

        let newMonthlyLimit = parseFloat(budget.monthly_limit);

        if (revResponse.ok) {
          const revData = await revResponse.json();
          if (revData.length > 0) {
            const revenue = parseFloat(revData[0].amount);
            const revenuePctCap = parseFloat(budget.revenue_pct_cap) || 80;
            newMonthlyLimit = (revenue * revenuePctCap) / 100;
          }
        }

        const updateResponse = await fetch(
          `${env.SUPABASE_URL}/rest/v1/customer_budgets?org_id=eq.${orgId}&cost_center=eq.${budget.cost_center}`,
          {
            method: 'PATCH',
            headers: getSupabaseHeaders(env),
            body: JSON.stringify({
              monthly_limit: newMonthlyLimit,
              last_refreshed_at: new Date().toISOString(),
              updated_at: new Date().toISOString()
            })
          }
        );

        if (updateResponse.ok) {
          refreshed.push({
            cost_center: budget.cost_center,
            previous_limit: parseFloat(budget.monthly_limit),
            new_limit: newMonthlyLimit
          });
        } else {
          failed.push({
            cost_center: budget.cost_center,
            reason: `Update failed: ${updateResponse.status}`
          });
        }
      } catch (budgetError) {
        failed.push({
          cost_center: budget.cost_center,
          reason: budgetError.message
        });
      }
    }

    return jsonResponse({
      orgId,
      period: currentPeriod,
      refreshed_count: refreshed.length,
      failed_count: failed.length,
      refreshed,
      failed
    });
  } catch (error) {
    console.error(`[CUSTOMER_BUDGETS] Refresh error: ${error.message}`);
    return errorResponse('INTERNAL_ERROR', error.message);
  }
}

