// ============ STRIPE INTEGRATION (C1) ============
// ============================================================================

async function callStripeAPI(endpoint, apiKey, method = 'GET', params = null) {
  const url = `https://api.stripe.com/v1${endpoint}`;
  const headers = {
    'Authorization': `Bearer ${apiKey}`,
    'Content-Type': 'application/x-www-form-urlencoded',
  };

  const options = { method, headers };

  if (params && method === 'GET') {
    const searchParams = new URLSearchParams(params);
    options.url = `${url}?${searchParams.toString()}`;
  } else if (params && method === 'POST') {
    options.body = new URLSearchParams(params).toString();
  }

  try {
    const response = await fetch(url, options);
    const data = await response.json();

    if (!response.ok) {
      throw new Error(data.error?.message || `Stripe API error: ${response.statusText}`);
    }

    return data;
  } catch (err) {
    throw new Error(`Stripe API call failed: ${err.message}`);
  }
}

async function handleListConnectors(request, env) {
  try {
    const orgId = getOrgIdFromAuth(request);
    if (!orgId) {
      return errorResponse('UNAUTHORIZED', 'Missing or invalid authorization', 401);
    }

    const supabaseUrl = env.SUPABASE_URL;
    const headers = getSupabaseHeaders(env);

    const response = await fetch(
      `${supabaseUrl}/rest/v1/revenue_connectors?org_id=eq.${orgId}`,
      { method: 'GET', headers }
    );

    if (!response.ok) {
      return errorResponse('DB_ERROR', 'Failed to retrieve connectors', 500);
    }

    const connectors = await response.json();

    const formatted = (connectors || []).map(connector => ({
      type: connector.connector_type,
      status: connector.status,
      last_sync_at: connector.last_sync_at,
      last_sync_status: connector.last_sync_status,
      invoices_synced: connector.invoices_synced,
      total_revenue_synced: connector.total_revenue_synced,
      sync_frequency: connector.sync_frequency,
      created_at: connector.created_at,
    }));

    return jsonResponse({
      connectors: formatted,
      total: formatted.length,
    });
  } catch (err) {
    console.error('handleListConnectors error:', err);
    return errorResponse('INTERNAL_ERROR', err.message, 500);
  }
}

async function handleConnectStripe(request, env) {
  try {
    const orgId = getOrgIdFromAuth(request);
    if (!orgId) {
      return errorResponse('UNAUTHORIZED', 'Missing or invalid authorization', 401);
    }

    const body = await request.json();
    const { api_key: apiKey, mapping = {} } = body;

    if (!apiKey) {
      return errorResponse('VALIDATION_ERROR', 'api_key is required');
    }

    if (!apiKey.match(/^(rk_live_|rk_test_)/)) {
      return errorResponse('VALIDATION_ERROR', 'Invalid Stripe API key format');
    }

    let accountInfo;
    try {
      accountInfo = await callStripeAPI('/v1/balance', apiKey);
    } catch (err) {
      return errorResponse('STRIPE_AUTH_FAILED', 'Invalid or expired Stripe API key', 401);
    }

    const connectorData = {
      org_id: orgId,
      connector_type: 'stripe',
      config: {
        api_key_preview: apiKey.substring(0, 10) + '...',
        api_key: apiKey,
      },
      status: 'active',
      cost_center_mapping: mapping,
    };

    const supabaseUrl = env.SUPABASE_URL;
    const headers = getSupabaseHeaders(env);

    const response = await fetch(`${supabaseUrl}/rest/v1/revenue_connectors`, {
      method: 'POST',
      headers: {
        ...headers,
        'Prefer': 'resolution=merge-duplicates',
      },
      body: JSON.stringify(connectorData),
    });

    if (!response.ok) {
      const error = await response.text();
      return errorResponse('DB_ERROR', `Failed to store connector: ${error}`, 500);
    }

    return jsonResponse({
      success: true,
      connector: {
        type: 'stripe',
        status: 'active',
        account_id: accountInfo.object,
        default_currency: accountInfo.default_currency,
      },
    }, 201);
  } catch (err) {
    console.error('handleConnectStripe error:', err);
    return errorResponse('INTERNAL_ERROR', err.message, 500);
  }
}

async function handleStripeSync(request, env) {
  try {
    const orgId = getOrgIdFromAuth(request);
    if (!orgId) {
      return errorResponse('UNAUTHORIZED', 'Missing or invalid authorization', 401);
    }

    // ITEM 2: Rate limit - 10/min per org for revenue sync
    const rlCheck = await rateLimit(env, `org:${orgId}:revenue_sync`, 10, 60);
    if (rlCheck) return rlCheck;

    const supabaseUrl = env.SUPABASE_URL;
    const headers = getSupabaseHeaders(env);

    const connectorResponse = await fetch(
      `${supabaseUrl}/rest/v1/revenue_connectors?org_id=eq.${orgId}&connector_type=eq.stripe`,
      { method: 'GET', headers }
    );

    if (!connectorResponse.ok) {
      return errorResponse('DB_ERROR', 'Failed to retrieve connector config', 500);
    }

    const connectors = await connectorResponse.json();
    if (!connectors || connectors.length === 0) {
      return errorResponse('NOT_FOUND', 'Stripe connector not configured', 404);
    }

    const connector = connectors[0];
    const apiKey = connector.config.api_key;
    const costCenterMapping = connector.cost_center_mapping || {};
    let connectorId = connector.id;

    let allInvoices = [];
    let hasMore = true;
    let startingAfter = null;

    try {
      while (hasMore) {
        const params = {
          status: 'paid',
          limit: 100,
        };
        if (startingAfter) {
          params.starting_after = startingAfter;
        }

        const invoiceData = await callStripeAPI('/v1/invoices', apiKey, 'GET', params);
        allInvoices = allInvoices.concat(invoiceData.data || []);

        hasMore = invoiceData.has_more || false;
        if (invoiceData.data && invoiceData.data.length > 0) {
          startingAfter = invoiceData.data[invoiceData.data.length - 1].id;
        }
      }
    } catch (err) {
      await fetch(`${supabaseUrl}/rest/v1/revenue_connectors?id=eq.${connectorId}`, {
        method: 'PATCH',
        headers,
        body: JSON.stringify({
          status: 'error',
          last_sync_status: 'failed',
          last_sync_error: err.message,
          last_sync_at: new Date().toISOString(),
        }),
      });

      return errorResponse('SYNC_FAILED', `Failed to fetch Stripe invoices: ${err.message}`, 500);
    }

    const syncResults = {
      synced: 0,
      skipped: 0,
      errors: [],
      new_customers_found: [],
    };

    let totalRevenuesynced = 0;

    for (const invoice of allInvoices) {
      try {
        const customerId = invoice.customer;
        let costCenter = null;

        if (costCenterMapping[customerId]) {
          costCenter = costCenterMapping[customerId];
        } else if (invoice.metadata?.finault_cost_center) {
          costCenter = invoice.metadata.finault_cost_center;
        } else {
          syncResults.new_customers_found.push({
            stripe_customer_id: customerId,
            invoice_id: invoice.id,
            amount: invoice.amount_paid / 100,
          });
          syncResults.skipped++;
          continue;
        }

        const periodDate = new Date(invoice.period_end * 1000);
        const period = `${periodDate.getFullYear()}-${String(periodDate.getMonth() + 1).padStart(2, '0')}`;

        const revenueEntry = {
          org_id: orgId,
          cost_center: costCenter,
          amount: invoice.amount_paid / 100,
          period,
          source: 'stripe',
          external_id: invoice.id,
          raw_metadata: {
            stripe_customer_id: customerId,
            invoice_number: invoice.number,
            currency: invoice.currency,
            description: invoice.description,
          },
        };

        const upsertUrl = `${supabaseUrl}/rest/v1/revenue_entries?on_conflict=external_id`;
        await fetch(upsertUrl, {
          method: 'POST',
          headers: {
            ...headers,
            'Prefer': 'resolution=merge-duplicates',
          },
          body: JSON.stringify(revenueEntry),
        });

        syncResults.synced++;
        totalRevenuesynced += revenueEntry.amount;
      } catch (invoiceErr) {
        syncResults.errors.push({
          invoice_id: invoice.id,
          error: invoiceErr.message,
        });
      }
    }

    try {
      await fetch(`${supabaseUrl}/rest/v1/revenue_connectors?id=eq.${connectorId}`, {
        method: 'PATCH',
        headers,
        body: JSON.stringify({
          last_sync_at: new Date().toISOString(),
          last_sync_status: 'success',
          invoices_synced: (connector.invoices_synced || 0) + syncResults.synced,
          total_revenue_synced: (parseFloat(connector.total_revenue_synced) || 0) + totalRevenuesynced,
          updated_at: new Date().toISOString(),
        }),
      });
    } catch (updateErr) {
      console.error('Failed to update connector metadata:', updateErr);
    }

    return jsonResponse({
      success: true,
      ...syncResults,
    });
  } catch (err) {
    console.error('handleStripeSync error:', err);
    return errorResponse('INTERNAL_ERROR', err.message, 500);
  }
}

/**
 * POST /v1/integrations/stripe/scan — Experience page: accept Stripe key directly, return customer data
 * No auth required. Uses the Time Machine Stripe fetcher.
 */
async function handleStripeScan(request, env) {
  try {
    const body = await request.json();
    const stripeKey = body.stripe_key || body.api_key;
    const customerLimit = Math.min(body.limit || 25, 50);
    if (!stripeKey) {
      return jsonResponse({ error: 'stripe_key is required' }, 400);
    }

    // Validate key format
    if (!stripeKey.startsWith('sk_test_') && !stripeKey.startsWith('sk_live_') && !stripeKey.startsWith('rk_test_') && !stripeKey.startsWith('rk_live_')) {
      return jsonResponse({ error: 'Invalid Stripe key format. Must start with sk_test_, sk_live_, rk_test_, or rk_live_.' }, 400);
    }

    // Fast Stripe scan: fetch customers + invoices with a cap
    const customers = await tmFetchStripeHistoryFast(stripeKey, customerLimit);

    // Build summary
    const customerSummary = customers.map(c => {
      const totalRevenue = (c.months || []).reduce((s, m) => s + (m.revenue || 0), 0);
      const latestMonth = (c.months || []).sort((a, b) => b.month.localeCompare(a.month))[0];
      return {
        name: c.name,
        email: c.email,
        stripe_customer_id: c.id,
        total_revenue: totalRevenue,
        mrr_usd: latestMonth?.mrr || 0,
        months_active: (c.months || []).length,
        revenue: totalRevenue,
        cost: 0, // Will be enriched by frontend from analysis data
        margin_percent: 100,
        underwater: false,
      };
    });

    return jsonResponse({
      success: true,
      customers: customerSummary,
      total_customers: customerSummary.length,
      total_revenue: customerSummary.reduce((s, c) => s + c.total_revenue, 0),
    });
  } catch (err) {
    console.error('handleStripeScan error:', err);
    return jsonResponse({ error: err.message }, 500);
  }
}

// ═══════════════════════════════════════════════════════════════════════
// EXPERIENCE PAGE: Close Pack generation from scan data (no auth)
// Takes the full scan results and generates a real Close Pack artifact
// ═══════════════════════════════════════════════════════════════════════
async function handleExperienceClosePack(request, env) {
  try {
    const body = await request.json();
    const { analysis, scoreData, savingsData, anomalyData, driftData, fcsData, customers } = body;

    if (!analysis) {
      return jsonResponse({ error: 'analysis data is required' }, 400);
    }

    const now = new Date();
    const period = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;

    // ── Transform scan data into invoice records for the real ClosePackGenerator ──
    // The generator expects an array of objects with { amount, provider, model, date, ... }
    const modelBreakdown = analysis.model_breakdown || [];
    const invoiceRecords = modelBreakdown.length > 0
      ? modelBreakdown.map((m, i) => ({
          id: `EXP-INV-${i + 1}`,
          amount: m.total_cost || m.cost || 0,
          provider: m.provider || 'openai',
          model: m.model || 'unknown',
          date: now.toISOString(),
          description: `AI usage: ${m.model || 'unknown'} — ${m.request_count || m.count || 0} requests`,
          category: 'AI_COMPUTE',
          department: 'Engineering',
          costCenter: 'AI-OPS',
          tokens: m.total_tokens || m.tokens || 0,
        }))
      : [{
          id: 'EXP-INV-1',
          amount: analysis.actual_total || 0,
          provider: (analysis.providers_analyzed || ['openai'])[0],
          model: (analysis.models_analyzed || ['unknown'])[0],
          date: now.toISOString(),
          description: `AI usage: ${analysis.record_count || 0} total API calls`,
          category: 'AI_COMPUTE',
          department: 'Engineering',
          costCenter: 'AI-OPS',
        }];

    // Build allocation data from customer margins
    const allocationRecords = (customers || []).map((c, i) => ({
      id: `ALLOC-${i + 1}`,
      sourceAccount: '5000',
      department: c.name || `Customer ${i + 1}`,
      amount: c.total_revenue || c.revenue || 0,
      percentage: 100,
      method: 'direct',
    }));

    // ── Use the REAL ClosePackGenerator (1,221 lines) ──
    // Create a fresh instance configured for this scan
    const generator = new ClosePackGenerator({
      companyName: body.companyName || 'Finault Experience Scan',
      companyId: `EXP-${Date.now()}`,
      fiscalYear: now.getFullYear(),
      fiscalMonth: now.getMonth() + 1,
      auditor: 'Finault Automated Audit Engine',
      format: 'professional',
      includeJournalEntries: true,
      includeReconciliation: true,
      includeAuditTrail: true,
      cryptographicSigning: true,
      supportedERPs: ['quickbooks', 'netsuite', 'sap', 'xero'],
    });

    // This generates all 9 documents:
    // executiveSummary, costAllocationReport, journalEntry, reconciliationCert,
    // controlsNarrative, varianceAnalysis, trendReport, budgetVsActual, evidenceBundle
    // Plus attestation with full hash chain
    const result = generator.generate(invoiceRecords, allocationRecords, {});

    // ── Enrich with experience-specific data ──
    const closePack = result.closePack || result;

    // Add Finault Score data
    closePack.finaultScore = {
      score: scoreData?.score || 0,
      grade: scoreData?.grade || 'N/A',
      dimensions: scoreData?.dimensions || {},
    };

    // Add savings intelligence
    closePack.savingsIntelligence = {
      totalRecoverable: savingsData?.total_recoverable || analysis.estimated_recoverable || 0,
      recommendations: (savingsData?.recommendations || []).map(r => ({
        category: r.category || r.type || 'optimization',
        description: r.description || r.title || '',
        estimatedSavings: r.estimated_savings || r.savings || 0,
        confidence: r.confidence || 'medium',
      })),
    };

    // Add anomaly report
    closePack.anomalyReport = {
      count: anomalyData?.anomalies?.length || 0,
      anomalies: (anomalyData?.anomalies || []).map(a => ({
        type: a.type || 'cost_spike',
        severity: a.severity || 'medium',
        description: a.description || a.message || '',
        impact: a.impact || a.cost_impact || 0,
      })),
    };

    // Add drift report
    closePack.driftReport = {
      events: driftData?.events || driftData?.drift_events || [],
      baselineStatus: driftData?.baseline_status || 'not_established',
    };

    // Add FCS report
    closePack.fcsReport = {
      score: fcsData?.score || fcsData?.fcs_score || null,
      dimensions: fcsData?.dimensions || fcsData?.evidence || {},
      status: fcsData?.status || 'computed',
    };

    // Add customer margin analysis
    closePack.customerMargins = (customers || []).map(c => ({
      name: c.name,
      revenue: c.total_revenue || c.revenue || 0,
      cost: c.cost || 0,
      margin: c.margin_percent || 100,
      status: c.underwater ? 'underwater' : 'healthy',
    }));

    // Add scan metadata
    closePack.scanMetadata = {
      totalAISpend: analysis.actual_total || 0,
      recordCount: analysis.record_count || 0,
      modelsAnalyzed: analysis.models_analyzed || [],
      providersAnalyzed: analysis.providers_analyzed || [],
      period,
    };

    // ── Store seal in Supabase ──
    const certId = closePack.id || `CP-EXP-${Date.now()}`;
    const sealHash = closePack.attestation?.hashChainRoot || closePack.attestation?.blockchainHash || '';
    const supaKey = (env.SUPABASE_SERVICE_KEY || env.SUPABASE_KEY) || env.SUPABASE_KEY;
    if (env.SUPABASE_URL && supaKey) {
      try {
        await fetch(`${env.SUPABASE_URL}/rest/v1/seals`, {
          method: 'POST',
          headers: {
            'apikey': supaKey,
            'Authorization': `Bearer ${supaKey}`,
            'Content-Type': 'application/json',
            'Prefer': 'return=minimal',
          },
          body: JSON.stringify({
            seal_id: certId,
            timestamp: now.toISOString(),
            model: 'n/a',
            provider: 'close_pack_experience',
            cost_usd: analysis.actual_total || 0,
            action: 'close_pack_sealed',
            tokens_used: 0,
            seal_hash: sealHash,
            prev_hash: '',
            sequence: 0,
          }),
        });
      } catch (e) {
        console.error('Failed to store close pack seal:', e);
      }
    }

    return jsonResponse({
      success: true,
      closePack,
      certId,
      sealHash,
      downloadReady: true,
    });
  } catch (err) {
    console.error('handleExperienceClosePack error:', err);
    return jsonResponse({ error: err.message }, 500);
  }
}

// ═══════════════════════════════════════════════════════════════════════
// EXPERIENCE PAGE: SOC 2 Report from scan data (no auth)
// ═══════════════════════════════════════════════════════════════════════
